INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\" />\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\" />\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\" />\n<title>TrainerCRM \u00b7 Crunch Cordova</title>\n<link rel=\"apple-touch-icon\" href=\"data:image/png;base64,\">\n<link rel=\"apple-touch-icon\" sizes=\"512x512\" href=\"data:image/png;base64,\">\n<link rel=\"icon\" type=\"image/png\" href=\"data:image/png;base64,\">\n<style>\n  *{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}\n  :root{--bg:#0b1120;--card:#111a2e;--card2:#0f1626;--line:#1e293b;--txt:#e7ecf5;--mut:#8494ad;--dim:#5b6b85;--ind:#6366f1;--ind2:#818cf8;--sky:#0ea5e9;--amb:#f59e0b;--grn:#22c55e;--org:#f97316;--red:#ef4444;}\n  html,body{margin:0;padding:0;background:var(--bg);color:var(--txt);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;-webkit-font-smoothing:antialiased;}\n  body{padding-bottom:78px;}\n  h1,h2,h3,h4{margin:0;}button{font-family:inherit;cursor:pointer;border:none;}\n  input,select,textarea{font-family:inherit;}\n  .wrap{max-width:640px;margin:0 auto;}\n  header{position:sticky;top:0;z-index:30;background:rgba(11,17,32,.96);backdrop-filter:blur(10px);border-bottom:1px solid var(--line);padding:14px 16px 12px;}\n  header .title{font-size:18px;font-weight:800;letter-spacing:-.3px;}header .sub{font-size:11px;color:var(--dim);margin-top:2px;}\n  nav{position:fixed;bottom:0;left:0;right:0;z-index:30;background:rgba(11,17,32,.97);backdrop-filter:blur(12px);border-top:1px solid var(--line);display:flex;padding:6px 2px calc(6px + env(safe-area-inset-bottom));}\n  nav button{flex:1;background:none;color:var(--dim);font-size:9.5px;font-weight:600;display:flex;flex-direction:column;align-items:center;gap:3px;padding:6px 2px;border-radius:10px;}\n  nav button.on{color:var(--ind2);}nav button{position:relative;}\n  .nav-badge{position:absolute;top:1px;left:calc(50% + 4px);min-width:16px;height:16px;padding:0 4px;border-radius:8px;background:#ef4444;color:#fff;font-size:10px;font-weight:800;display:flex;align-items:center;justify-content:center;line-height:1;box-shadow:0 0 0 2px #0b1120;}\n  .brief{margin-bottom:14px;}\n  .brief-hi{font-size:21px;font-weight:800;letter-spacing:-.3px;}\n  .brief-date{font-size:12px;color:var(--dim);margin-top:1px;}\n  .brief-sum{font-size:13px;color:#c3cee0;margin-top:9px;line-height:1.4;}nav button svg{width:20px;height:20px;}\n  .view{display:none;padding:16px;}.view.on{display:block;}\n  .card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:14px;}.card+.card{margin-top:10px;}\n  .row{display:flex;align-items:center;gap:10px;}\n  .stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;}\n  .stat{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px 6px;text-align:center;}\n  .stat .v{font-size:20px;font-weight:800;color:#fff;}.stat .l{font-size:9px;text-transform:uppercase;letter-spacing:.4px;color:var(--dim);margin-top:3px;}\n  .chips{display:flex;gap:8px;overflow-x:auto;padding:2px 0;margin:14px 0 12px;}\n  .chip{white-space:nowrap;font-size:12px;font-weight:600;padding:7px 13px;border-radius:999px;background:var(--card2);border:1px solid var(--line);color:var(--mut);}\n  .chip.on{background:var(--ind);border-color:var(--ind);color:#fff;}\n  .lead{width:100%;text-align:left;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:13px;display:flex;align-items:center;gap:9px;margin-bottom:8px;}\n  .lead:active{border-color:#33415c;}\n  .lead .nm{font-weight:700;color:#fff;font-size:15px;}.lead .mt{font-size:11px;color:var(--dim);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n  .badge{font-size:10px;font-weight:700;padding:4px 8px;border-radius:8px;white-space:nowrap;}\n  .flex1{flex:1;min-width:0;}\n  .fab{position:fixed;right:18px;bottom:86px;z-index:31;width:56px;height:56px;border-radius:50%;background:var(--ind);color:#fff;font-size:30px;line-height:1;display:flex;align-items:center;justify-content:center;box-shadow:0 10px 24px rgba(79,70,229,.45);}\n  .alert{display:flex;align-items:center;gap:9px;background:rgba(245,158,11,.1);border:1px solid rgba(245,158,11,.3);color:#fcd34d;border-radius:14px;padding:11px 14px;font-size:13px;font-weight:600;margin-bottom:10px;width:100%;text-align:left;}\n  .alert.red{background:rgba(239,68,68,.1);border-color:rgba(239,68,68,.3);color:#fca5a5;}\n  .ov{position:fixed;inset:0;z-index:40;background:rgba(0,0,0,.6);display:none;align-items:flex-end;}.ov.on{display:flex;}\n  .sheet{width:100%;max-width:640px;margin:0 auto;background:var(--bg);border-top:1px solid var(--line);border-radius:20px 20px 0 0;max-height:90vh;overflow-y:auto;}\n  .sheet .sh-h{position:sticky;top:0;background:var(--bg);display:flex;align-items:center;justify-content:space-between;padding:15px 16px;border-bottom:1px solid var(--line);}\n  .sheet .sh-h h2{font-size:17px;font-weight:800;}.sheet .sh-b{padding:16px;}\n  .x{background:none;color:var(--dim);font-size:22px;line-height:1;padding:4px;}\n  label.fld{display:block;margin-bottom:12px;}label.fld span{display:block;font-size:11px;color:var(--dim);margin-bottom:5px;}\n  .inp{width:100%;background:var(--card2);border:1px solid var(--line);border-radius:12px;padding:11px 12px;font-size:15px;color:var(--txt);outline:none;}.inp:focus{border-color:var(--ind);}\n  textarea.inp{min-height:80px;resize:vertical;line-height:1.5;}\n  .btn{width:100%;background:var(--ind);color:#fff;font-weight:700;font-size:15px;padding:13px;border-radius:13px;}.btn:disabled{opacity:.4;}\n  .btn.ghost{background:var(--card2);border:1px solid var(--line);color:var(--txt);}.btn.sky{background:rgba(14,165,233,.16);border:1px solid rgba(14,165,233,.4);color:#7dd3fc;}\n  .btn.grn{background:var(--grn);}.btn.red{background:rgba(239,68,68,.14);border:1px solid rgba(239,68,68,.4);color:#fca5a5;}.btn.sm{font-size:13px;padding:9px;width:auto;}\n  .stage-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:6px 0 4px;}\n  .stage-b{font-size:12px;font-weight:600;padding:10px;border-radius:11px;background:var(--card2);border:1px solid var(--line);color:var(--mut);}\n  .hist{max-height:190px;overflow-y:auto;}.hist .h{font-size:12px;color:var(--mut);display:flex;gap:8px;padding:3px 0;}.hist .h .d{color:var(--dim);white-space:nowrap;}\n  .lbl{font-size:10px;text-transform:uppercase;letter-spacing:.5px;color:var(--dim);margin:14px 0 7px;}\n  .search{width:100%;background:var(--card2);border:1px solid var(--line);border-radius:12px;padding:10px 12px;font-size:14px;color:var(--txt);outline:none;margin-bottom:2px;}\n  .search:focus{border-color:var(--ind);}\n  /* Today card */\n  .today{background:linear-gradient(135deg,#1a1440,#111a2e);border:1px solid #2b2170;border-radius:16px;padding:14px;margin-bottom:12px;}\n  .today .th{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;}\n  .today .th b{font-size:14px;color:#fff;}\n  .today .th .goal{font-size:11px;color:var(--ind2);font-weight:600;}\n  .tcount{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:12px;}\n  .tcount div{text-align:center;}.tcount .ic{font-size:16px;line-height:1;margin-bottom:2px;}.today .th{gap:8px;}.tcount .v{font-size:22px;font-weight:800;color:#fff;}.tcount .l{font-size:9px;text-transform:uppercase;letter-spacing:.3px;color:var(--mut);margin-top:2px;}\n  .bar{height:8px;background:#0b1120;border-radius:99px;overflow:hidden;}\n  .bar>div{height:100%;background:linear-gradient(90deg,var(--ind),var(--sky));border-radius:99px;transition:width .3s;}\n  .goalrow{display:flex;justify-content:space-between;font-size:11px;color:var(--mut);margin-top:6px;}\n  /* funnel + chart */\n  .funnel .fr{display:flex;align-items:center;gap:10px;margin-bottom:8px;}\n  .funnel .fbar{flex:1;height:30px;border-radius:8px;display:flex;align-items:center;padding:0 10px;font-size:12px;font-weight:700;color:#fff;min-width:44px;}\n  .funnel .flabel{width:96px;font-size:12px;color:var(--mut);}.funnel .fpct{width:38px;text-align:right;font-size:11px;color:var(--dim);}\n  .chart{display:flex;align-items:flex-end;gap:6px;height:120px;padding:8px 0 0;}\n  .chart .col{flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;height:100%;justify-content:flex-end;}\n  .chart .stk{width:70%;display:flex;flex-direction:column-reverse;border-radius:4px 4px 0 0;overflow:hidden;min-height:2px;}\n  .chart .day{font-size:9px;color:var(--dim);}\n  .guide h2{font-size:20px;font-weight:800;letter-spacing:-.4px;margin-bottom:4px;}.guide .tag{font-size:12px;color:var(--ind2);font-weight:600;margin-bottom:14px;}\n  .guide h3{font-size:15px;font-weight:700;color:#fff;margin:18px 0 7px;}\n  .guide p{font-size:14px;line-height:1.62;color:#c3cee0;margin:0 0 11px;}\n  .guide ul{margin:0 0 12px;padding-left:2px;list-style:none;}.guide li{font-size:14px;line-height:1.6;color:#c3cee0;padding-left:18px;position:relative;margin-bottom:8px;}\n  .guide li::before{content:\"\";position:absolute;left:2px;top:9px;width:6px;height:6px;border-radius:50%;background:var(--ind);}\n  .guide .quote{background:var(--card2);border-left:3px solid var(--ind);border-radius:0 10px 10px 0;padding:11px 13px;font-size:13.5px;line-height:1.55;color:#dce4f2;font-style:italic;margin:0 0 12px;}\n  .guide .callout{background:rgba(99,102,241,.09);border:1px solid rgba(99,102,241,.25);border-radius:12px;padding:12px 14px;margin:4px 0 14px;}\n  .guide .callout p{margin:0;color:#d7deec;font-size:13.5px;}.guide .callout .cl-t{font-weight:700;color:var(--ind2);font-size:12px;text-transform:uppercase;letter-spacing:.4px;margin-bottom:5px;}\n  .warn{background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.25);border-radius:12px;padding:12px 14px;margin:4px 0 14px;}.warn p{margin:0;font-size:13px;color:#fca5a5;line-height:1.55;}\n  .tpl{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:13px;margin-bottom:10px;}.tpl .th{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;}.tpl .th b{font-size:14px;color:#fff;}\n  .tpl .body{font-size:13px;color:var(--mut);line-height:1.55;white-space:pre-line;}\n  .copy{font-size:12px;font-weight:600;background:var(--card2);border:1px solid var(--line);color:var(--txt);padding:6px 11px;border-radius:9px;}.copy.done{background:var(--grn);border-color:var(--grn);color:#052e12;}\n  .empty{text-align:center;color:var(--dim);font-size:14px;padding:50px 20px;}.mini{font-size:12px;color:var(--dim);line-height:1.5;}\n  .q-card{text-align:center;padding:22px 16px;}.q-card .q-nm{font-size:22px;font-weight:800;color:#fff;}.q-card .q-src{font-size:12px;color:var(--dim);margin-top:3px;}\n  .q-prev{background:var(--card2);border:1px solid var(--line);border-radius:12px;padding:12px;font-size:13.5px;line-height:1.55;color:#d7deec;text-align:left;white-space:pre-line;margin:16px 0;}.q-count{font-size:12px;color:var(--dim);text-align:center;margin-top:10px;}\n  .price-tbl{width:100%;border-collapse:collapse;margin:2px 0 12px;font-size:13px;}\n  .price-tbl th{text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.3px;color:var(--dim);padding:6px 8px;border-bottom:1px solid var(--line);}\n  .price-tbl td{padding:8px;border-bottom:1px solid var(--line);color:#c3cee0;}.price-tbl td b{color:#fff;}.price-tbl .promo{color:var(--grn);font-weight:700;}\n  .stepnum{display:inline-flex;width:22px;height:22px;border-radius:50%;background:var(--ind);color:#fff;font-size:12px;font-weight:800;align-items:center;justify-content:center;margin-right:8px;}\n  .cmd-title{font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:var(--dim);margin:2px 0 8px;}\n  .cmd-row{width:100%;display:flex;align-items:center;gap:11px;border:1px solid var(--line);border-radius:14px;padding:12px 14px;margin-bottom:8px;text-align:left;}\n  .cmd-row:active{transform:scale(.99);}\n  .cmd-n{font-size:15px;font-weight:800;white-space:nowrap;}\n  .cmd-l{flex:1;font-size:13px;color:#d7deec;font-weight:600;}\n  .cmd-ar{color:var(--dim);font-size:18px;}\n  .cmd-clear{text-align:center;color:#4ade80;font-size:13px;padding:16px;border:1px solid rgba(34,197,94,.25);background:rgba(34,197,94,.08);border-radius:14px;margin-bottom:6px;}\n  #authScreen{display:none;position:fixed;inset:0;z-index:70;background:radial-gradient(120% 80% at 50% -10%,#241a5e,#0b1120 60%);align-items:center;justify-content:center;padding:24px;}\n  .authbox{width:100%;max-width:360px;text-align:center;}\n  .authbox .brand{font-size:24px;font-weight:900;letter-spacing:-.4px;}\n  .authbox .tag{font-size:12px;color:var(--dim);margin-bottom:20px;}\n  .authbox h2{font-size:19px;font-weight:800;margin:4px 0 16px;}\n  .authbox .inp{margin-bottom:10px;text-align:left;}\n  .authswitch{margin-top:16px;color:var(--mut);}.authswitch a{color:var(--ind2);font-weight:700;}\n  .aerr{color:#fca5a5;font-size:13px;min-height:17px;margin:2px 0 4px;}\n  .exp{font-size:10px;font-weight:700;padding:3px 7px;border-radius:7px;white-space:nowrap;}\n</style>\n</head>\n<body>\n<div id=\"authScreen\"></div>\n<div class=\"wrap\">\n  <header><div class=\"title\">TrainerHub</div><div class=\"sub\">Crunch Cordova \u00b7 kickoff outreach</div></header>\n\n  <section class=\"view on\" id=\"v-pipeline\">\n    <div id=\"typeToggle\"></div>\n    <div id=\"brief\"></div>\n    <div id=\"cmd\"></div>\n    <div class=\"today\" id=\"todayCard\"></div>\n    <input class=\"search\" id=\"searchBox\" placeholder=\"Search name or number...\" oninput=\"renderLeads()\">\n    <div class=\"chips\" id=\"filters\"></div>\n    <div id=\"leadList\"></div>\n  </section>\n\n  <section class=\"view\" id=\"v-agenda\">\n    <h3 style=\"font-size:16px;font-weight:800;margin-bottom:2px;\">Agenda</h3>\n    <p class=\"mini\" style=\"margin-bottom:6px;\">Your upcoming kickoff appointments, soonest first.</p>\n    <div id=\"agendaList\"></div>\n  </section>\n  <section class=\"view\" id=\"v-stats\">\n    <h3 style=\"font-size:16px;font-weight:800;margin-bottom:2px;\">Your funnel</h3>\n    <p class=\"mini\" style=\"margin-bottom:12px;\">Where people fall off. Each drop has a different fix (see Guides).</p>\n    <div class=\"card funnel\" id=\"funnel\"></div>\n    <h3 style=\"font-size:16px;font-weight:800;margin:18px 0 2px;\">Last 7 days</h3>\n    <p class=\"mini\" style=\"margin-bottom:12px;\">Texts sent and appointments booked per day.</p>\n    <div class=\"card\"><div class=\"chart\" id=\"chart\"></div>\n      <div class=\"row\" style=\"justify-content:center;gap:16px;margin-top:12px;font-size:11px;color:var(--mut);\">\n        <span><span style=\"display:inline-block;width:9px;height:9px;background:var(--ind);border-radius:2px;margin-right:4px;\"></span>Texts</span>\n        <span><span style=\"display:inline-block;width:9px;height:9px;background:var(--grn);border-radius:2px;margin-right:4px;\"></span>Scheduled</span></div>\n    </div>\n    <div class=\"stat-grid\" id=\"allTime\" style=\"margin-top:16px;\"></div>\n    <h3 style=\"font-size:16px;font-weight:800;margin:20px 0 2px;\">Team leaderboard</h3>\n    <p class=\"mini\" style=\"margin-bottom:10px;\">Ranked by revenue sold. Shows once trainers are assigned to leads.</p>\n    <div id=\"leaderboard\"></div>\n    <div class=\"card\" style=\"margin-top:12px;\">\n      <div class=\"row\" style=\"justify-content:space-between;\"><div class=\"mini\">Sales booked (all-time)</div><div id=\"salesVal\" style=\"font-weight:800;\">$0</div></div>\n      <div class=\"row\" style=\"justify-content:space-between;margin-top:12px;padding-top:12px;border-top:1px solid var(--line);\"><div><b style=\"font-size:14px;\">Your commission</b> <button id=\"commRate\" onclick=\"editLevel()\" style=\"background:none;color:var(--ind2);font-size:11px;font-weight:700;\">(40% &#9998;)</button><div class=\"mini\" id=\"commMonth\"></div></div><div id=\"commVal\" style=\"font-size:26px;font-weight:800;color:var(--grn);\">$0</div></div></div>\n  </section>\n\n  <section class=\"view\" id=\"v-grow\">\n    <div class=\"card\">\n      <h3 style=\"font-size:16px;font-weight:800;margin-bottom:6px;\">Self sign-up form</h3>\n      <p class=\"mini\" style=\"margin-bottom:12px;\">Let people add themselves. Every submission lands straight in your New Leads &mdash; no copy/paste. Put the link in your Instagram bio, or show the QR on the gym floor.</p>\n      <a class=\"btn\" href=\"/intake\" target=\"_blank\" style=\"text-decoration:none;text-align:center;display:block;\">Open my sign-up form</a>\n      <div class=\"row\" style=\"gap:8px;margin-top:8px;\">\n        <button class=\"btn ghost sm\" style=\"flex:1;\" onclick=\"copyIntakeLink()\">Copy link</button>\n        <button class=\"btn ghost sm\" style=\"flex:1;\" onclick=\"showQR()\">Show QR code</button>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3 style=\"font-size:15px;font-weight:700;margin-bottom:8px;\">Log an Instagram / DM lead</h3>\n      <input id=\"g_name\" class=\"inp\" placeholder=\"Name or @handle\" style=\"margin-bottom:8px;\">\n      <input id=\"g_contact\" class=\"inp\" placeholder=\"Phone or @handle\" style=\"margin-bottom:8px;\">\n      <input id=\"g_goal\" class=\"inp\" placeholder=\"Goal (optional)\" style=\"margin-bottom:10px;\">\n      <button class=\"btn\" onclick=\"addDM()\">Add DM lead</button>\n    </div>\n    <h3 class=\"lbl\">Top referrers</h3>\n    <div id=\"refBoard\"></div>\n    <h3 class=\"lbl\">Leads by source</h3>\n    <div id=\"srcBoard\" class=\"card\"></div>\n    <div class=\"callout\" style=\"margin-top:14px;background:rgba(99,102,241,.09);border:1px solid rgba(99,102,241,.25);border-radius:12px;padding:12px 14px;\"><p style=\"margin:0;color:#d7deec;font-size:13px;\">Ask <b>every</b> kickoff and client: \"Know anyone who'd want a free Kickoff?\" Log them here with the referrer's name &mdash; referrals close far higher than cold leads.</p></div>\n  </section>\n  <section class=\"view\" id=\"v-import\">\n    <div class=\"card\">\n      <h3 style=\"font-size:16px;font-weight:800;margin-bottom:6px;\">Load a kickoff report</h3>\n      <p class=\"mini\" style=\"margin-bottom:12px;\">Upload your report file (PDF, CSV, or Excel) &mdash; it reads name, phone, email, calendar-pending, and expiration, and skips anyone already in your list.</p>\n      <input type=\"file\" id=\"reportFile\" accept=\".pdf,.csv,.xlsx,.xls\" style=\"display:none;\" onchange=\"uploadReport()\">\n      <button class=\"btn\" onclick=\"document.getElementById('reportFile').click()\">Upload report file</button>\n      <p class=\"mini\" style=\"text-align:center;margin:10px 0;color:#5b6b85;\">or paste the text</p>\n      <textarea class=\"inp\" id=\"reportBox\" placeholder=\"Paste the full report text here...\" style=\"min-height:120px;\"></textarea>\n      <button class=\"btn\" style=\"margin-top:10px;\" onclick=\"importReport()\">Import from report</button>\n      <div id=\"importResult\"></div>\n    </div>\n    <div class=\"card\">\n      <h3 style=\"font-size:15px;font-weight:700;margin-bottom:6px;\">Add one quickly</h3>\n      <p class=\"mini\" style=\"margin-bottom:10px;\">Format: <code>First,Last,Phone,Email,Source,ReferredBy,Goal</code> (only first name needed). Paste web-form submissions here.</p>\n      <textarea class=\"inp\" id=\"pasteBox\" placeholder=\"Jordan,Smith,901-555-0100,jordan@email.com\"></textarea>\n      <button class=\"btn\" style=\"margin-top:10px;\" onclick=\"importPaste()\">Add</button>\n    </div>\n    <div class=\"warn\"><p><b>Keep yourself covered:</b> use this only to work your assigned kickoff list &mdash; members contacting about the session they paid for. Keep it on your phone, don't repurpose the numbers, and clear anyone who's no longer a Crunch prospect. Confirm your club is fine with working the report on your phone.</p></div>\n    <button class=\"btn ghost\" onclick=\"exportCSV()\">Export pipeline (backup CSV)</button>\n    <button class=\"btn ghost\" style=\"margin-top:8px;color:#f87171;\" onclick=\"resetAll()\">Reset all data</button>\n    <p class=\"mini\" style=\"text-align:center;margin-top:8px;\">Data lives only in this browser. Back it up before clearing browser data.</p>\n    <div id=\"teamPanel\" style=\"margin-top:16px;\"></div>\n  </section>\n\n  <section class=\"view\" id=\"v-outreach\">\n    <div class=\"card\">\n      <h3 style=\"font-size:16px;font-weight:800;margin-bottom:6px;\">Rapid text queue</h3>\n      <p class=\"mini\" style=\"margin-bottom:12px;\">Walks you through un-texted leads, soonest-to-expire first. One tap opens your text app with their name filled in. Personal, fast, compliant.</p>\n      <div class=\"row\" style=\"gap:8px;margin-bottom:10px;\">\n        <input class=\"inp\" id=\"slot1\" placeholder=\"Slot 1 (e.g. Tue 5pm)\" oninput=\"setSlots()\">\n        <input class=\"inp\" id=\"slot2\" placeholder=\"Slot 2 (e.g. Wed 9am)\" oninput=\"setSlots()\">\n      </div>\n      <p class=\"mini\" style=\"margin:-4px 0 10px;color:#5b6b85;\">Set your two open times once \\u2014 they auto-fill every text below.</p>\n      <div class=\"row\" style=\"gap:8px;\">\n        <label class=\"fld\" style=\"flex:1;\"><span>Script</span><select class=\"inp\" id=\"queueTpl\" onchange=\"renderQueue()\"></select></label>\n        <label class=\"fld\" style=\"flex:1;\"><span>Show</span><select class=\"inp\" id=\"queueSeg\" onchange=\"renderQueue()\"><option value=\"all\">All un-texted</option><option value=\"expiring\">Expiring soon</option><option value=\"new\">New leads</option></select></label>\n      </div>\n      <div id=\"queueArea\"></div>\n    </div>\n    <h3 class=\"lbl\">Your templates</h3>\n    <div id=\"tplList\"></div>\n  </section>\n\n  <section class=\"view\" id=\"v-guides\">\n    <div class=\"chips\" id=\"guideTabs\"></div>\n    <div class=\"guide\" id=\"guideBody\"></div>\n  </section>\n</div>\n\n<nav id=\"nav\"></nav>\n<button class=\"fab\" id=\"fab\" onclick=\"openAdd()\">+</button>\n<div class=\"ov\" id=\"ov\"><div class=\"sheet\"><div class=\"sh-h\"><h2 id=\"ovTitle\"></h2><button class=\"x\" onclick=\"closeOv()\">&times;</button></div><div class=\"sh-b\" id=\"ovBody\"></div></div></div>\n\n<script>\nvar SEED=[];\nvar STAGES=[\n {k:\"new\",l:\"Not Contacted\",c:\"#64748b\"},{k:\"reached\",l:\"Texted\",c:\"#6366f1\"},\n {k:\"replied\",l:\"Replied\",c:\"#0ea5e9\"},{k:\"scheduled\",l:\"Scheduled\",c:\"#f59e0b\"},\n {k:\"showed\",l:\"Showed / Kickoff\",c:\"#f97316\"},{k:\"sold\",l:\"Sold PT\",c:\"#22c55e\"},\n {k:\"noresp\",l:\"No Response\",c:\"#475569\"},{k:\"dead\",l:\"Not Interested\",c:\"#3f4a5e\"}\n];\nvar TEMPLATES=[\n {name:\"First Text (short)\",body:\"Hey [First Name]! This is [Trainer], one of the trainers at Crunch Cordova. You've got a free 60-min CrunchONE Kickoff on your account \\u2014 goal-setting plus a 30-min workout built for you.\\n\\nI've got a couple openings this week: [Day 6pm] or [Day 10am]. Which works better?\"},\n {name:\"New lead / signup reply\",body:\"Hey [First Name]! This is [Trainer], a trainer at Crunch Cordova \\u2014 thanks for reaching out! I'd love to get you in for a FREE fitness assessment: we'll go over your goals and I'll take you through a workout. I've got [Day 6pm] or [Day 10am] open this week \\u2014 which works better?\"},\n {name:\"Expiring soon (urgency)\",body:\"Hey [First Name]! [Trainer] from Crunch Cordova \\u2014 your free CrunchONE Kickoff is about to expire and I'd hate for you to lose it. I can still get you in this week: [Day 6pm] or [Day 10am]. Want me to lock one in?\"},\n {name:\"Follow-up Nudge (24h)\",body:\"Hey [First Name], still want to grab that Kickoff? Don't want you to lose it :) I can hold [Day/Time] for you.\"},\n {name:\"Second Nudge / last call\",body:\"Hey [First Name] \\u2014 last spot I've got this week is [Day/Time]. Want me to save it before it's gone?\"},\n {name:\"Voicemail Script\",body:\"Hey [First Name], it's [Trainer] from Crunch Cordova \\u2014 you've got a free fitness assessment on your account and I've got a couple spots open this week. Shoot me a text back and I'll get you set up. Talk soon!\"}\n];\nvar SOURCES=[\"Kickoff report\",\"Walk-in\",\"Referral\",\"Instagram DM\",\"Content\",\"Booth / QR\",\"Web form\",\"Manual\"];\nvar PT_VALUE=420; // conservative est. revenue per sold PT agreement (3x 60min EFT draft)\n\nvar API=\"\";\nvar TOKEN=(function(){try{return localStorage.getItem(\"trainercrm_token\")||\"\";}catch(e){return \"\";}})();\nvar ME=null;\nvar TRAINER=(function(){try{return localStorage.getItem(\"trainercrm_trainer\")||\"\";}catch(e){return \"\";}})();\nvar SLOT1=(function(){try{return localStorage.getItem(\"trainercrm_slot1\")||\"\";}catch(e){return \"\";}})();\nvar SLOT2=(function(){try{return localStorage.getItem(\"trainercrm_slot2\")||\"\";}catch(e){return \"\";}})();\nfunction trainerFirst(){return (ME&&ME.name)?ME.name.split(\" \")[0]:\"your trainer\";}\nfunction slotFill(body,first){var s=body.replace(/\\[First Name\\]/g,first||\"\").replace(/\\[Trainer\\]/g,trainerFirst());if(SLOT1)s=s.replace(/\\[Day 6pm\\]/g,SLOT1).replace(/\\[Day\\/Time\\]/g,SLOT1);if(SLOT2)s=s.replace(/\\[Day 10am\\]/g,SLOT2);return s;}\nfunction setSlots(){var a=document.getElementById(\"slot1\"),b=document.getElementById(\"slot2\");SLOT1=a?a.value:SLOT1;SLOT2=b?b.value:SLOT2;try{localStorage.setItem(\"trainercrm_slot1\",SLOT1);localStorage.setItem(\"trainercrm_slot2\",SLOT2);}catch(e){}renderQueue();}\nfunction pickTemplate(l){var by=function(n){for(var i=0;i<TEMPLATES.length;i++)if(TEMPLATES[i].name===n)return TEMPLATES[i].body;return TEMPLATES[0].body;};\n  if(isContentLead(l)&&l.stage===\"new\")return by(\"New lead / signup reply\");\n  var d=daysUntilExpire(l);\n  if(l.stage===\"new\"&&d!==null&&d>=0&&d<=3)return by(\"Expiring soon (urgency)\");\n  if(l.stage===\"new\")return by(\"First Text (short)\");\n  if(l.stage===\"reached\")return by(\"Follow-up Nudge (24h)\");\n  if(l.stage===\"noresp\")return by(\"Second Nudge / last call\");\n  return by(\"First Text (short)\");}\nfunction copyStageText(id){var l=null;state.leads.forEach(function(x){if(x.id===id)l=x;});if(!l)return;var t=slotFill(pickTemplate(l),l.firstName);try{if(navigator.clipboard)navigator.clipboard.writeText(t);}catch(e){}alert(\"Copied the right text for this stage \\u2014 paste it into your messages:\\n\\n\"+t);}\nvar state={leads:[],events:[],goal:30,level:\"PT3\"};\nvar filter=\"priority\",guideTab=\"cheatsheet\",leadType=\"kickoff\",current=\"pipeline\",queueIdx=0;\nfunction hdrs(){var x={\"Content-Type\":\"application/json\"};if(TOKEN)x[\"Authorization\"]=\"Bearer \"+TOKEN;return x;}\nasync function api(m,p,b){var r=await fetch(API+p,{method:m,headers:hdrs(),body:b!=null?JSON.stringify(b):undefined});if(r.status===401){TOKEN=\"\";ME=null;try{localStorage.removeItem(\"trainercrm_token\");}catch(e){}showAuth();throw new Error(\"unauthorized\");}if(!r.ok)throw new Error(\"api \"+r.status);if(r.status===204)return null;return await r.json();}\nasync function refresh(){try{var s=await api(\"GET\",\"/api/state\");state.leads=s.leads;state.events=s.events;state.goal=s.settings.goal;state.level=s.settings.level;}catch(e){console.log(e);}renderAll();}\nfunction renderAll(){renderPipeline();renderOutreach();renderGrow();renderNav();if(current===\"stats\")renderStats();if(current===\"guides\")renderGuideTabs();if(current===\"agenda\")renderAgenda();}\nfunction rateOf(){var m={PT1:.30,PT2:.35,PT3:.40,\"Master PT\":.45,\"Elite PT\":.50};return m[state.level]||.40;}\nfunction renderHeader(){var el=document.getElementById(\"who\");if(el)el.innerHTML=ME?esc(ME.name):\"\";}\nfunction showAuth(){var el=document.getElementById(\"authScreen\");el.style.display=\"flex\";renderAuth(\"login\");}\nfunction hideAuth(){document.getElementById(\"authScreen\").style.display=\"none\";}\nasync function boot(){if(!TOKEN){showAuth();return;}try{ME=await api(\"GET\",\"/api/me\");TRAINER=ME.name;hideAuth();renderHeader();refresh();}catch(e){showAuth();}}\nfunction renderAuth(mode){\n  var reg=(mode===\"register\");\n  var html='<div class=\"authbox\"><div class=\"brand\">TrainerCRM</div><div class=\"tag\">Crunch Cordova</div>'\n    +'<h2>'+(reg?\"Create your account\":\"Trainer login\")+'</h2>'\n    +(reg?'<input class=\"inp\" id=\"au_name\" placeholder=\"Your name (shown on leads)\">':'')\n    +'<input class=\"inp\" id=\"au_user\" placeholder=\"Username\" autocapitalize=\"none\" autocorrect=\"off\">'\n    +'<input class=\"inp\" id=\"au_pass\" type=\"password\" placeholder=\"Password\">'\n    +(reg?'<input class=\"inp\" id=\"au_code\" placeholder=\"Invite code (leave blank if first user)\">':'')\n    +'<div class=\"aerr\" id=\"au_err\"></div>'\n    +'<button class=\"btn\" onclick=\"'+(reg?\"doRegister()\":\"doLogin()\")+'\">'+(reg?\"Create account\":\"Log in\")+'</button>'\n    +'<p class=\"authswitch mini\">'+(reg?'Have an account? <a onclick=\"renderAuth(\\'login\\')\">Log in</a>':'New trainer? <a onclick=\"renderAuth(\\'register\\')\">Create account</a>')+'</p></div>';\n  document.getElementById(\"authScreen\").innerHTML=html;\n}\nasync function authPost(path,body){var r=await fetch(API+path,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(body)});var d=null;try{d=await r.json();}catch(e){}if(!r.ok)throw new Error((d&&d.detail)||\"Something went wrong\");return d;}\nasync function doLogin(){var e=document.getElementById(\"au_err\");e.textContent=\"\";try{var d=await authPost(\"/api/login\",{username:document.getElementById(\"au_user\").value.trim(),password:document.getElementById(\"au_pass\").value});TOKEN=d.token;try{localStorage.setItem(\"trainercrm_token\",TOKEN);}catch(x){}ME=d.user;TRAINER=ME.name;hideAuth();renderHeader();refresh();}catch(err){e.textContent=err.message;}}\nasync function doRegister(){var e=document.getElementById(\"au_err\");e.textContent=\"\";try{var d=await authPost(\"/api/register\",{name:document.getElementById(\"au_name\").value.trim(),username:document.getElementById(\"au_user\").value.trim(),password:document.getElementById(\"au_pass\").value,code:document.getElementById(\"au_code\").value.trim()});TOKEN=d.token;try{localStorage.setItem(\"trainercrm_token\",TOKEN);}catch(x){}ME=d.user;TRAINER=ME.name;hideAuth();renderHeader();refresh();}catch(err){e.textContent=err.message;}}\nasync function logout(){try{await api(\"POST\",\"/api/logout\");}catch(e){}TOKEN=\"\";ME=null;try{localStorage.removeItem(\"trainercrm_token\");}catch(x){}showAuth();}\nasync function claimLead(id){if(!TRAINER){setTrainer();return;}try{await api(\"PATCH\",\"/api/leads/\"+id,{assignedTo:TRAINER});}catch(e){}await refresh();openDetail(id);}\nasync function claimQuick(id){if(!TRAINER)return;try{await api(\"PATCH\",\"/api/leads/\"+id,{assignedTo:TRAINER});}catch(e){}await refresh();}\nasync function openReassign(id){\n  var l=null;state.leads.forEach(function(x){if(x.id===id)l=x;});if(!l)return;\n  var trainers=[];try{trainers=await api(\"GET\",\"/api/trainers\");}catch(e){}\n  var btns=trainers.map(function(t){var on=(t.name===l.assignedTo);\n    return '<button class=\"btn '+(on?'':'ghost')+' sm\" style=\"width:100%;margin-bottom:6px;\" onclick=\"reassignTo(\\''+id+'\\',\\''+encodeURIComponent(t.name)+'\\')\">'+esc(t.name)+(t.isAdmin?' \\u00b7 admin':'')+(on?' \\u2713':'')+'</button>';}).join(\"\");\n  if(!btns)btns='<p class=\"mini\">No trainers found.</p>';\n  openOv(\"Reassign \\u2014 \"+((l.firstName+\" \"+(l.lastName||\"\")).trim()),\n    btns+'<button class=\"btn ghost sm\" style=\"width:100%;margin-top:8px;color:#94a3b8;\" onclick=\"reassignTo(\\''+id+'\\',\\'\\')\">Unassign (return to pool)</button>');\n}\nasync function reassignTo(id,nameEnc){var name=decodeURIComponent(nameEnc||\"\");try{await api(\"PATCH\",\"/api/leads/\"+id,{assignedTo:name});}catch(e){}await refresh();openDetail(id);}\n\nvar uid=function(){return Math.random().toString(36).slice(2,10);};\nvar now=function(){return new Date().toISOString();};\nvar todayKey=function(){var d=new Date();return d.getFullYear()+\"-\"+(d.getMonth()+1)+\"-\"+d.getDate();};\nfunction dayKeyOf(d){return d.getFullYear()+\"-\"+(d.getMonth()+1)+\"-\"+d.getDate();}\nvar stageMeta=function(k){for(var i=0;i<STAGES.length;i++)if(STAGES[i].k===k)return STAGES[i];return STAGES[0];};\nfunction daysSince(iso){if(!iso)return null;return Math.floor((Date.now()-new Date(iso).getTime())/864e5);}\nfunction fmtDate(iso){return new Date(iso).toLocaleDateString(undefined,{month:\"short\",day:\"numeric\"});}\nfunction esc(s){return (s||\"\").replace(/[&<>\"]/g,function(c){return{\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c];});}\nfunction digits(s){return (s||\"\").replace(/[^\\d]/g,\"\");}\nfunction parseMDY(s){if(!s)return null;var m=s.match(/(\\d{1,2})\\/(\\d{1,2})\\/(\\d{4})/);if(!m)return null;return new Date(+m[3],+m[1]-1,+m[2]);}\nfunction daysUntilExpire(l){var d=parseMDY(l.expire);if(!d)return null;return Math.ceil((d-new Date())/864e5);}\n\nfunction textStreak(){\n  var days={};state.events.forEach(function(e){if(e.type===\"text\")days[dayKeyOf(new Date(e.at))]=1;});\n  var streak=0,d=new Date();\n  // allow today to be 0 without breaking the streak (count from yesterday)\n  if(!days[dayKeyOf(d)])d.setDate(d.getDate()-1);\n  while(days[dayKeyOf(d)]){streak++;d.setDate(d.getDate()-1);}\n  return streak;\n}\nfunction logEvent(type,amount){state.events.push({type:type,at:now(),amount:amount||0});}\n\n/* server-backed: no client seed */\n\n/* ---------- TODAY CARD ---------- */\nfunction countToday(type){var tk=todayKey();return state.events.filter(function(e){return e.type===type&&dayKeyOf(new Date(e.at))===tk;}).length;}\nfunction renderToday(){\n  var texted=countToday(\"text\"),sched=countToday(\"schedule\"),sold=countToday(\"sold\"),replied=countToday(\"reply\");\n  var pct=Math.min(100,Math.round(texted/state.goal*100));\n  var soldAmtToday=state.events.filter(function(e){return e.type===\"sold\"&&dayKeyOf(new Date(e.at))===todayKey();}).reduce(function(a,e){return a+(e.amount||0);},0);\n  var commToday=Math.round(soldAmtToday*rateOf());\n  var streak=textStreak();\n  var streakBadge=streak>0?'<span style=\"font-size:11px;font-weight:800;color:#fb923c;\">\\ud83d\\udd25 '+streak+' day streak</span>':'';\n  document.getElementById(\"todayCard\").innerHTML=\n    '<div class=\"th\"><b>Today</b>'+streakBadge+'<button class=\"goal\" style=\"background:none;\" onclick=\"editGoal()\">Goal: '+state.goal+' &#9998;</button></div>'+\n    '<div class=\"tcount\">'+\n    '<div><div class=\"ic\">\\ud83d\\udcf1</div><div class=\"v\">'+texted+'</div><div class=\"l\">Texted</div></div>'+\n    '<div><div class=\"ic\">\\ud83d\\udcac</div><div class=\"v\" style=\"color:#7dd3fc;\">'+replied+'</div><div class=\"l\">Replies</div></div>'+\n    '<div><div class=\"ic\">\\ud83d\\udcc5</div><div class=\"v\" style=\"color:#fbbf24;\">'+sched+'</div><div class=\"l\">Scheduled</div></div>'+\n    '<div><div class=\"ic\">\\ud83d\\udcb0</div><div class=\"v\" style=\"color:#4ade80;\">'+sold+'</div><div class=\"l\">Sold</div></div></div>'+\n    '<div class=\"bar\"><div style=\"width:'+pct+'%;\"></div></div>'+\n    '<div class=\"goalrow\"><span>'+texted+' / '+state.goal+' texts</span><span>'+(texted>=state.goal?\"Goal hit! \\ud83d\\udd25\":(state.goal-texted)+\" to go\")+'</span></div>'+\n    (commToday>0?'<div class=\"goalrow\" style=\"margin-top:5px;padding-top:8px;border-top:1px solid #2b2170;\"><span>Commission booked today</span><span style=\"color:#4ade80;font-weight:800;\">$'+commToday.toLocaleString()+'</span></div>':'');\n}\nasync function editGoal(){var v=prompt(\"Daily text goal:\",state.goal);if(v&&!isNaN(+v)){state.goal=Math.max(1,parseInt(v));try{await api(\"PUT\",\"/api/settings\",{goal:state.goal,level:state.level});}catch(e){}renderToday();}}\nasync function editLevel(){var lv=[\"PT1\",\"PT2\",\"PT3\",\"Master PT\",\"Elite PT\"];var v=prompt(\"Your PT level (\"+lv.join(\", \")+\"):\",state.level);if(v){if(lv.indexOf(v)<0){alert(\"Enter one of: \"+lv.join(\", \"));return;}state.level=v;try{await api(\"PUT\",\"/api/settings\",{goal:state.goal,level:v});}catch(e){}renderStats();renderPipeline();}}\nfunction openEditProfile(id){\n  var l=null;state.leads.forEach(function(x){if(x.id===id)l=x;});if(!l)return;\n  function fld(lbl,fid,val,ph,type){return '<label class=\"fld\"><span>'+lbl+'</span><input class=\"inp\" id=\"'+fid+'\" value=\"'+esc(val||\"\")+'\" placeholder=\"'+(ph||\"\")+'\"'+(type?' type=\"'+type+'\"':'')+'></label>';}\n  var isClient=[\"showed\",\"sold\"].indexOf(l.stage)>=0;\n  var clientFields=isClient?(\n     fld(\"Package sold\",\"p_pkg\",l.package,\"e.g. 3x/wk 60min\")\n    +fld(\"Sale value ($)\",\"p_sale\",l.saleValue||\"\",\"2100\",\"tel\")\n    +fld(\"Weight\",\"p_wt\",l.weight,\"185 lbs\")\n    +fld(\"Body fat %\",\"p_bf\",l.bodyFat,\"22\")\n    +fld(\"Measurements\",\"p_ms\",l.measurements,\"Waist 34, Arm 15...\")\n  ):(\n     '<input type=\"hidden\" id=\"p_pkg\" value=\"'+esc(l.package||\"\")+'\"><input type=\"hidden\" id=\"p_sale\" value=\"'+esc((l.saleValue||\"\")+\"\")+'\"><input type=\"hidden\" id=\"p_wt\" value=\"'+esc(l.weight||\"\")+'\"><input type=\"hidden\" id=\"p_bf\" value=\"'+esc(l.bodyFat||\"\")+'\"><input type=\"hidden\" id=\"p_ms\" value=\"'+esc(l.measurements||\"\")+'\">'\n    +'<p class=\"mini\" style=\"margin:-4px 0 12px;color:#5b6b85;\">Weight, body fat & package appear once they\\'ve shown up or bought PT.</p>'\n  );\n  openOv(\"Edit \\u2014 \"+((l.firstName+\" \"+(l.lastName||\"\")).trim()),\n    fld(\"Goal\",\"p_goal\",l.goal,\"Lose weight, build muscle...\")\n    +fld(\"Next follow-up\",\"p_fu\",l.nextFollowUp,\"\",\"date\")\n    +fld(\"Appointment\",\"p_appt\",l.appointment,\"\",\"datetime-local\")\n    +fld(\"Assigned trainer\",\"p_assigned\",l.assignedTo,\"Trainer name\")\n    +clientFields\n    +'<button class=\"btn\" onclick=\"saveProfile(\\''+id+'\\')\">Save details</button>');\n}\nasync function saveProfile(id){\n  var g=function(x){return document.getElementById(x).value;};\n  var sale=parseFloat((g(\"p_sale\")+\"\").replace(/[^0-9.]/g,\"\"));\n  var body={goal:g(\"p_goal\"),package:g(\"p_pkg\"),weight:g(\"p_wt\"),bodyFat:g(\"p_bf\"),measurements:g(\"p_ms\"),nextFollowUp:g(\"p_fu\"),appointment:g(\"p_appt\"),assignedTo:g(\"p_assigned\")};\n  if(!isNaN(sale))body.saleValue=sale;\n  try{await api(\"PATCH\",\"/api/leads/\"+id,body);}catch(e){}\n  await refresh();openDetail(id);\n}\nasync function editSale(id){var l=null;state.leads.forEach(function(x){if(x.id===id)l=x;});if(!l)return;var v=prompt(\"Sale amount ($):\",l.saleValue||\"\");if(v!=null){var n=parseFloat((v+\"\").replace(/[^0-9.]/g,\"\"));try{await api(\"PATCH\",\"/api/leads/\"+id,{saleValue:isNaN(n)?0:n});}catch(e){}await refresh();openDetail(id);}}\n\n/* ---------- PIPELINE ---------- */\nfunction parseYMD(s){if(!s)return null;var m=(\"\"+s).match(/(\\d{4})-(\\d{2})-(\\d{2})/);if(!m)return null;return new Date(+m[1],+m[2]-1,+m[3]);}\nfunction followUps(){var out=[],seen={},t=new Date();t.setHours(0,0,0,0);\n  state.leads.forEach(function(l){\n    if([\"sold\",\"dead\"].indexOf(l.stage)>=0||isBooked(l)||!ofType(l))return;\n    var due=false;\n    var f=parseYMD(l.nextFollowUp);if(f&&f<=t)due=true;\n    if([\"reached\",\"replied\",\"scheduled\"].indexOf(l.stage)>=0&&daysSince(l.lastContact)!==null&&daysSince(l.lastContact)>=2)due=true;\n    if(due&&!seen[l.id]){seen[l.id]=1;out.push(l);}\n  });return out;}\nfunction needsFollowUp(){return followUps();}\nfunction expiringSoon(){return state.leads.filter(function(l){var d=daysUntilExpire(l);return !isBooked(l)&&ofType(l)&&d!==null&&d>=0&&d<=7&&[\"new\",\"reached\",\"replied\"].indexOf(l.stage)>=0;});}\nfunction computeStats(){\n  var L=state.leads,t=L.length;\n  var reached=L.filter(function(l){return l.stage!==\"new\";}).length;\n  var replied=L.filter(function(l){return [\"replied\",\"scheduled\",\"showed\",\"sold\"].indexOf(l.stage)>=0;}).length;\n  var sched=L.filter(function(l){return [\"scheduled\",\"showed\",\"sold\"].indexOf(l.stage)>=0;}).length;\n  var sold=L.filter(function(l){return l.stage===\"sold\";}).length;\n  var pct=function(n,d){return d?Math.round(n/d*100):0;};\n  return {t:t,reached:reached,replied:replied,sched:sched,sold:sold,reply:pct(replied,reached),schedR:pct(sched,replied),close:pct(sold,sched)};\n}\nfunction renderFilters(){\n  var fu=needsFollowUp().length,ex=expiringSoon().length,nl=contentLeads().length;\n  var ml=state.leads.filter(function(l){return TRAINER&&l.assignedTo===TRAINER&&ofType(l)&&[\"sold\",\"dead\"].indexOf(l.stage)<0;}).length;\n  var opts=[[\"priority\",\"\\ud83c\\udfaf Priority\"],[\"active\",leadType===\"sga\"?\"SGA List\":\"Kickoff List\"]];\n  if(TRAINER)opts.push([\"mine\",\"My Leads (\"+ml+\")\"]);\n  var bk=state.leads.filter(function(l){return isBooked(l)&&ofType(l);}).length;\n  opts=opts.concat([[\"newleads\",\"New Leads (\"+nl+\")\"],[\"expiring\",\"Expiring (\"+ex+\")\"],[\"followup\",\"Follow-up (\"+fu+\")\"],[\"scheduled\",\"Scheduled\"]]);\n  if(bk)opts.push([\"booked\",\"Already Booked (\"+bk+\")\"]);\n  opts=opts.concat([[\"won\",\"Sold\"],[\"all\",\"All\"]]);\n  document.getElementById(\"filters\").innerHTML=opts.map(function(o){return '<button class=\"chip '+(filter===o[0]?\"on\":\"\")+'\" onclick=\"setFilter(\\''+o[0]+'\\')\">'+o[1]+'</button>';}).join(\"\");\n}\nfunction isContentLead(l){return (l.source||\"\")!==\"Kickoff report\";}\nfunction isBooked(l){return l.pending===\"1\";}\nfunction ofType(l){return (l.type||\"kickoff\")===leadType;}\nfunction setLeadType(t){leadType=t;filter=\"priority\";renderPipeline();window.scrollTo({top:0,behavior:\"smooth\"});}\nfunction renderTypeToggle(){var el=document.getElementById(\"typeToggle\");if(!el)return;function seg(t,lbl){return '<button onclick=\"setLeadType(\\''+t+'\\')\" style=\"flex:1;padding:9px;border-radius:10px;font-weight:800;font-size:13px;'+(leadType===t?'background:var(--ind);color:#fff;':'background:transparent;color:var(--dim);')+'\">'+lbl+'</button>';}el.innerHTML='<div style=\"display:flex;gap:4px;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:4px;margin-bottom:14px;\">'+seg(\"kickoff\",\"Kickoffs\")+seg(\"sga\",\"SGAs\")+'</div>';}\nfunction sortByNew(arr){return arr.slice().sort(function(a,b){return (new Date(b.createdAt||0))-(new Date(a.createdAt||0));});}\nfunction isoLocal(d){var p=function(n){return (n<10?\"0\":\"\")+n;};return d.getFullYear()+\"-\"+p(d.getMonth()+1)+\"-\"+p(d.getDate())+\"T\"+p(d.getHours())+\":\"+p(d.getMinutes());}\nfunction defaultAppt(){var d=new Date();d.setDate(d.getDate()+1);d.setHours(18,0,0,0);return isoLocal(d);}\nfunction apptLeads(){return state.leads.filter(function(l){return l.appointment&&[\"scheduled\",\"showed\"].indexOf(l.stage)>=0;}).sort(function(a,b){return new Date(a.appointment)-new Date(b.appointment);});}\nfunction appointmentsToday(){var t=new Date().toDateString();return state.leads.filter(function(l){return l.appointment&&[\"scheduled\",\"showed\"].indexOf(l.stage)>=0&&new Date(l.appointment).toDateString()===t;});}\nfunction dayLabel(d){var t=new Date();t.setHours(0,0,0,0);var dd=new Date(d);dd.setHours(0,0,0,0);var diff=Math.round((dd-t)/864e5);if(diff===0)return \"Today\";if(diff===1)return \"Tomorrow\";if(diff===-1)return \"Yesterday\";return dd.toLocaleDateString(undefined,{weekday:\"long\",month:\"short\",day:\"numeric\"});}\nfunction openSchedule(id){\n  var l=null;state.leads.forEach(function(x){if(x.id===id)l=x;});if(!l)return;\n  openOv(\"Schedule \\u2014 \"+((l.firstName+\" \"+(l.lastName||\"\")).trim()),\n    '<label class=\"fld\"><span>Appointment date & time</span><input class=\"inp\" id=\"ap_dt\" type=\"datetime-local\" value=\"'+esc(l.appointment||defaultAppt())+'\"></label><button class=\"btn grn\" onclick=\"saveSchedule(\\''+id+'\\')\">Save appointment</button><p class=\"mini\" style=\"margin-top:10px;\">This marks them Scheduled and adds it to your Agenda.</p>');\n}\nasync function saveSchedule(id){var v=document.getElementById(\"ap_dt\").value;try{await api(\"POST\",\"/api/leads/\"+id+\"/stage\",{stage:\"scheduled\",appointment:v});}catch(e){}await refresh();openDetail(id);}\nfunction priorityScore(l){\n  if([\"sold\",\"dead\",\"noresp\"].indexOf(l.stage)>=0)return -1;\n  if(isBooked(l))return -1;\n  var s=0,d=daysUntilExpire(l);\n  if(l.stage===\"replied\")s+=60;else if(l.stage===\"new\")s+=20;else if(l.stage===\"reached\")s+=15;else if(l.stage===\"scheduled\")s+=22;else if(l.stage===\"showed\")s+=18;\n  if(d!==null){if(d<0)s+=4;else if(d<=2)s+=50;else if(d<=5)s+=34;else if(d<=10)s+=20;else s+=8;}\n  if(l.stage===\"new\"&&isContentLead(l))s+=30;\n  var ds=daysSince(l.lastContact);\n  if([\"reached\",\"replied\"].indexOf(l.stage)>=0&&ds!==null&&ds>=2)s+=15;\n  var f=parseYMD(l.nextFollowUp),t=new Date();t.setHours(0,0,0,0);if(f&&f<=t)s+=25;\n  return s;\n}\nfunction priorityReason(l){\n  var d=daysUntilExpire(l),f=parseYMD(l.nextFollowUp),t=new Date();t.setHours(0,0,0,0),ds=daysSince(l.lastContact);\n  if(l.stage===\"replied\")return {t:\"Replied \\u2014 close it\",c:\"#22c55e\"};\n  if(f&&f<=t)return {t:\"Follow-up due\",c:\"#f59e0b\"};\n  if(d!==null&&d>=0&&d<=2)return {t:d+\"d to expire\",c:\"#ef4444\"};\n  if(l.stage===\"new\"&&isContentLead(l))return {t:\"New signup\",c:\"#0ea5e9\"};\n  if(d!==null&&d>=0&&d<=5)return {t:d+\"d to expire\",c:\"#f59e0b\"};\n  if(l.stage===\"reached\"&&ds!==null&&ds>=2)return {t:\"No reply \"+ds+\"d \\u2014 call\",c:\"#fbbf24\"};\n  if(l.stage===\"scheduled\")return {t:\"Confirm appt\",c:\"#f97316\"};\n  if(d!==null&&d<0)return {t:\"Expired\",c:\"#64748b\"};\n  if(l.stage===\"new\")return {t:\"Not contacted\",c:\"#818cf8\"};\n  return {t:\"\",c:\"\"};\n}\nfunction priorityLeads(){return state.leads.filter(function(l){return priorityScore(l)>=0&&ofType(l);}).sort(function(a,b){return priorityScore(b)-priorityScore(a);});}\nfunction contentLeads(){return sortByNew(state.leads.filter(function(l){return isContentLead(l)&&ofType(l)&&[\"new\",\"reached\",\"replied\"].indexOf(l.stage)>=0;}));}\nfunction sortByExpire(arr){return arr.slice().sort(function(a,b){var da=daysUntilExpire(a),db=daysUntilExpire(b);if(da===null)da=9999;if(db===null)db=9999;if(da!==db)return da-db;return (new Date(b.createdAt||0))-(new Date(a.createdAt||0));});}\nfunction visibleLeads(){\n  var L=state.leads.filter(ofType),q=digits(document.getElementById(\"searchBox\")?document.getElementById(\"searchBox\").value:\"\");\n  var qtext=(document.getElementById(\"searchBox\")?document.getElementById(\"searchBox\").value:\"\").toLowerCase().trim();\n  var base;\n  if(filter===\"priority\")base=priorityLeads();\n  else if(filter===\"active\")base=sortByExpire(L.filter(function(l){return [\"new\",\"reached\",\"replied\"].indexOf(l.stage)>=0&&!isBooked(l);}));\n  else if(filter===\"booked\")base=L.filter(function(l){return isBooked(l);});\n  else if(filter===\"mine\")base=sortByExpire(state.leads.filter(function(l){return l.assignedTo===TRAINER&&[\"new\",\"reached\",\"replied\",\"scheduled\",\"showed\"].indexOf(l.stage)>=0;}));\n  else if(filter===\"newleads\")base=contentLeads();\n  else if(filter===\"expiring\")base=sortByExpire(expiringSoon());\n  else if(filter===\"followup\")base=needsFollowUp();\n  else if(filter===\"scheduled\")base=L.filter(function(l){return [\"scheduled\",\"showed\"].indexOf(l.stage)>=0;});\n  else if(filter===\"won\")base=L.filter(function(l){return l.stage===\"sold\";});\n  else base=L;\n  if(qtext)base=base.filter(function(l){return (l.firstName+\" \"+l.lastName).toLowerCase().indexOf(qtext)>=0||(q&&digits(l.phone).indexOf(q)>=0);});\n  return base;\n}\nfunction expBadge(l){\n  var d=daysUntilExpire(l);if(d===null)return \"\";\n  if(d<0)return '<span class=\"exp\" style=\"background:#3f4a5e;color:#94a3b8;\">expired</span>';\n  if(d<=3)return '<span class=\"exp\" style=\"background:#ef444422;color:#f87171;\">'+d+'d left</span>';\n  if(d<=7)return '<span class=\"exp\" style=\"background:#f59e0b22;color:#fbbf24;\">'+d+'d left</span>';\n  return '<span class=\"exp\" style=\"background:#1e293b;color:#64748b;\">'+d+'d</span>';\n}\nfunction renderLeads(){\n  var el=document.getElementById(\"leadList\"),L=visibleLeads();\n  if(!L.length){el.innerHTML='<div class=\"empty\">Nothing here.<br>Load your report on the Import tab.</div>';return;}\n  var banner=\"\";\n  if(filter===\"priority\"){\n    var rep=L.filter(function(l){return l.stage===\"replied\";}).length;\n    var exp=L.filter(function(l){var d=daysUntilExpire(l);return d!==null&&d>=0&&d<=5;}).length;\n    var fresh=L.filter(function(l){return l.stage===\"new\"&&isContentLead(l);}).length;\n    var bits=[];if(rep)bits.push(rep+\" replied waiting\");if(exp)bits.push(exp+\" expiring soon\");if(fresh)bits.push(fresh+\" new signup\"+(fresh>1?\"s\":\"\"));\n    var line=bits.length?(\"Start at the top \\u2014 \"+bits.join(\" \\u00b7 \")+\".\"):\"Work top to bottom \\u2014 highest-value leads first.\";\n    banner='<div class=\"card\" style=\"margin-bottom:10px;background:linear-gradient(135deg,#141a3a,#111a2e);border-color:#2b2170;\"><div style=\"font-size:12px;color:#818cf8;font-weight:800;letter-spacing:.3px;margin-bottom:3px;\">\\ud83c\\udfaf WHO TO TEXT FIRST</div><div style=\"font-size:13px;color:#d7deec;\">'+line+'</div></div>';\n  }\n  el.innerHTML=banner+L.map(function(l){\n    var m=stageMeta(l.stage),d=daysSince(l.lastContact);\n    var dChip=(d!==null&&[\"reached\",\"replied\",\"scheduled\"].indexOf(l.stage)>=0)?'<span style=\"font-size:10px;color:'+(d>=2?\"#fbbf24\":\"#5b6b85\")+';\">'+d+'d</span>':'';\n    var asgChip=l.assignedTo?'<span class=\"badge\" style=\"background:#6366f122;color:#a5b4fc;\">\\ud83d\\udc64 '+esc(l.assignedTo.split(\" \")[0])+'</span>':'';\n    var bookedChip=isBooked(l)?'<span class=\"badge\" style=\"background:#22c55e22;color:#4ade80;\">\\u2713 booked</span>':'';\n    var claimChip=(filter===\"priority\"&&!l.assignedTo&&TRAINER)?'<span class=\"badge\" style=\"background:#6366f133;color:#c7d2fe;border:1px solid #6366f155;\" onclick=\"event.stopPropagation();claimQuick(\\''+l.id+'\\')\">+ Claim</span>':'';\n    var srcChip=isContentLead(l)?'<span class=\"badge\" style=\"background:#0ea5e922;color:#7dd3fc;\">'+esc(l.source)+'</span>':'';\n    if(filter===\"priority\"){\n      var pr=priorityReason(l);\n      var prChip=pr.t?'<span class=\"badge\" style=\"background:'+pr.c+'22;color:'+pr.c+';\">'+pr.t+'</span>':'';\n      return '<button class=\"lead\" onclick=\"openDetail(\\''+l.id+'\\')\"><div class=\"flex1\"><div class=\"nm\">'+esc(l.firstName)+' '+esc(l.lastName||\"\")+'</div><div class=\"mt\">'+esc(l.phone||l.email||\"\")+'</div></div>'+asgChip+claimChip+prChip+dChip+'<span class=\"badge\" style=\"background:'+m.c+'22;color:'+m.c+';\">'+m.l+'</span></button>';\n    }\n    return '<button class=\"lead\" onclick=\"openDetail(\\''+l.id+'\\')\"><div class=\"flex1\"><div class=\"nm\">'+esc(l.firstName)+' '+esc(l.lastName||\"\")+'</div><div class=\"mt\">'+esc(l.phone||l.email||\"\")+'</div></div>'+asgChip+bookedChip+srcChip+expBadge(l)+dChip+'<span class=\"badge\" style=\"background:'+m.c+'22;color:'+m.c+';\">'+m.l+'</span></button>';\n  }).join(\"\");\n}\nfunction renderAgenda(){\n  var L=apptLeads(),el=document.getElementById(\"agendaList\");if(!el)return;\n  if(!L.length){el.innerHTML='<div class=\"empty\">No appointments yet.<br>Tap a lead \\u2192 Mark Scheduled to add one.</div>';return;}\n  var groups={},order=[];\n  L.forEach(function(l){var key=new Date(l.appointment).toDateString();if(!groups[key]){groups[key]=[];order.push(key);}groups[key].push(l);});\n  var html=\"\";\n  order.forEach(function(key){\n    html+='<div class=\"lbl\" style=\"margin-top:16px;\">'+dayLabel(new Date(key))+'</div>';\n    groups[key].forEach(function(l){\n      var t=new Date(l.appointment),time=t.toLocaleTimeString([],{hour:\"numeric\",minute:\"2-digit\"}),m=stageMeta(l.stage);var tt=(l.type===\"sga\")?'<span class=\"badge\" style=\"background:#8b5cf622;color:#c4b5fd;\">SGA</span>':'';\n      html+='<button class=\"lead\" onclick=\"openDetail(\\''+l.id+'\\')\"><div style=\"width:66px;font-size:13px;font-weight:800;color:#fb923c;\">'+time+'</div><div class=\"flex1\"><div class=\"nm\">'+esc(l.firstName)+' '+esc(l.lastName||\"\")+'</div><div class=\"mt\">'+esc(l.goal||l.phone||\"\")+'</div></div><span class=\"badge\" style=\"background:'+m.c+'22;color:'+m.c+';\">'+m.l+'</span></button>';\n    });\n  });\n  el.innerHTML=html;\n}\nfunction renderBriefing(){\n  var el=document.getElementById(\"brief\");if(!el)return;\n  var hr=new Date().getHours();var greet=hr<12?\"Good morning\":(hr<18?\"Good afternoon\":\"Good evening\");\n  var name=ME&&ME.name?ME.name.split(\" \")[0]:\"\";\n  var date=new Date().toLocaleDateString(undefined,{weekday:\"long\",month:\"long\",day:\"numeric\"});\n  var ex=expiringSoon().length,fu=followUps().length,apt=appointmentsToday().length;\n  var bits=[];\n  if(apt)bits.push(\"\\ud83d\\udcc5 \"+apt+\" appointment\"+(apt>1?\"s\":\"\")+\" today\");\n  if(ex)bits.push(\"\\ud83d\\udd25 \"+ex+\" expiring soon\");\n  if(fu)bits.push(\"\\u23f0 \"+fu+\" follow-up\"+(fu>1?\"s\":\"\")+\" due\");\n  var summary=bits.length?bits.join(\"  \\u00b7  \"):\"You're all caught up \\u2014 a great time to prospect and post content.\";\n  el.innerHTML='<div class=\"brief\"><div class=\"brief-hi\">'+greet+(name?\", \"+esc(name):\"\")+' \\ud83d\\udc4b</div><div class=\"brief-date\">'+date+'</div><div class=\"brief-sum\">'+summary+'</div></div>';\n}\nasync function renderTeam(){\n  var el=document.getElementById(\"teamPanel\");if(!el)return;\n  if(!(ME&&ME.isAdmin)){el.innerHTML=\"\";return;}\n  var users=[];try{users=await api(\"GET\",\"/api/trainers\");}catch(e){}\n  var rows=users.map(function(u){var me=(u.id===ME.id);\n    return '<div class=\"lead\"><div class=\"flex1\"><div class=\"nm\">'+esc(u.name)+(u.isAdmin?' <span style=\"font-size:10px;color:#a5b4fc;\">admin</span>':'')+(me?' <span style=\"font-size:10px;color:#5b6b85;\">(you)</span>':'')+'</div></div>'\n      +'<button class=\"btn ghost sm\" style=\"width:auto;margin:0 4px;\" onclick=\"resetUserPw(\\''+u.id+'\\',\\''+encodeURIComponent(u.name)+'\\')\">Reset PW</button>'\n      +(me?'':'<button class=\"btn ghost sm\" style=\"width:auto;color:#f87171;\" onclick=\"removeUser(\\''+u.id+'\\',\\''+encodeURIComponent(u.name)+'\\')\">Remove</button>')\n      +'</div>';}).join(\"\");\n  el.innerHTML='<div class=\"card\"><h3 style=\"font-size:15px;font-weight:800;margin-bottom:4px;\">Team accounts</h3><p class=\"mini\" style=\"margin-bottom:10px;\">Reset a trainer\\'s password or remove their access. Removing a trainer returns their leads to the shared pool. New trainers sign up with your invite code.</p>'+rows+'</div>';\n}\nasync function resetUserPw(id,nameEnc){var name=decodeURIComponent(nameEnc);var pw=prompt(\"Set a new temporary password for \"+name+\":\");if(!pw)return;try{await api(\"POST\",\"/api/users/\"+id+\"/password\",{password:pw});alert(name+\"\\u2019s password was reset. Tell them to log in with the new password.\");}catch(e){alert(\"Couldn\\u2019t reset \\u2014 password needs 4+ characters.\");}}\nasync function removeUser(id,nameEnc){var name=decodeURIComponent(nameEnc);if(!confirm(\"Remove \"+name+\"\\u2019s access? Their leads return to the shared pool.\"))return;try{await api(\"DELETE\",\"/api/users/\"+id);}catch(e){}await renderTeam();await refresh();}\nfunction renderCommandCenter(){\n  var ex=expiringSoon().length,fu=followUps().length,apt=appointmentsToday().length,nl=contentLeads().length;\n  function cmdGo(f){if(f===\"agenda\")go(\"agenda\");else setFilter(f);}\n  function card(emoji,n,label,color,filt){return '<button class=\"cmd-row\" style=\"border-color:'+color+'55;background:'+color+'14;\" onclick=\"cmdGo(\\''+filt+'\\')\"><span class=\"cmd-n\" style=\"color:'+color+';\">'+emoji+' '+n+'</span><span class=\"cmd-l\">'+label+'</span><span class=\"cmd-ar\">\\u203a</span></button>';}\n  var rows=[];\n  if(ex>0)rows.push(card(\"\\ud83d\\udd25\",ex,\"Expiring within 7 days\",\"#ef4444\",\"expiring\"));\n  if(fu>0)rows.push(card(\"\\u23f0\",fu,\"Follow-ups due\",\"#f59e0b\",\"followup\"));\n  if(apt>0)rows.push(card(\"\\ud83d\\udcc5\",apt,(apt>1?\"Appointments today\":\"Appointment today\"),\"#f97316\",\"agenda\"));\n  if(nl>0)rows.push(card(\"\\u2728\",nl,\"New leads waiting\",\"#0ea5e9\",\"newleads\"));\n  var el=document.getElementById(\"cmd\");if(!el)return;\n  el.innerHTML=rows.length?('<div class=\"cmd-title\">What to do today</div>'+rows.join(\"\")):'<div class=\"cmd-clear\">\\u2705 You\\'re all caught up. Nice work.</div>';\n}\nfunction setFilter(f){filter=f;renderFilters();renderLeads();window.scrollTo({top:0,behavior:\"smooth\"});}\nfunction renderPipeline(){renderTypeToggle();renderBriefing();renderCommandCenter();renderToday();renderFilters();renderLeads();}\n\n/* ---------- STATS ---------- */\nfunction renderLeaderboard(){\n  var el=document.getElementById(\"leaderboard\");if(!el)return;\n  var map={};\n  state.leads.forEach(function(l){var t=(l.assignedTo||\"\").trim();if(!t)return;if(!map[t])map[t]={appts:0,sold:0,rev:0};\n    if([\"scheduled\",\"showed\",\"sold\"].indexOf(l.stage)>=0)map[t].appts++;\n    if(l.stage===\"sold\"){map[t].sold++;map[t].rev+=(l.saleValue||0);}});\n  var arr=Object.keys(map).map(function(k){var o=map[k];return {name:k,appts:o.appts,sold:o.sold,rev:o.rev};}).sort(function(a,b){return b.rev-a.rev||b.sold-a.sold||b.appts-a.appts;});\n  if(!arr.length){el.innerHTML='<div class=\"card\"><p class=\"mini\">No assigned leads yet. Assign leads to trainers (or claim them) to build the board.</p></div>';return;}\n  var medals=[\"\\ud83e\\udd47\",\"\\ud83e\\udd48\",\"\\ud83e\\udd49\"];\n  el.innerHTML=arr.map(function(r,i){var me=(ME&&r.name===ME.name);\n    return '<div class=\"lead\" style=\"'+(me?\"border-color:#6366f1;\":\"\")+'\"><div style=\"width:34px;font-size:16px;font-weight:800;color:#818cf8;text-align:center;\">'+(medals[i]||(\"#\"+(i+1)))+'</div><div class=\"flex1\"><div class=\"nm\">'+esc(r.name)+(me?' <span style=\"font-size:10px;color:#818cf8;\">(you)</span>':'')+'</div><div class=\"mt\">'+r.appts+' appts \\u00b7 '+r.sold+' sold</div></div><div style=\"font-weight:800;color:#4ade80;\">$'+Math.round(r.rev).toLocaleString()+'</div></div>';\n  }).join(\"\");\n}\nfunction renderStats(){\n  var s=computeStats();\n  var steps=[[\"Leads\",s.t,\"#64748b\",100],[\"Texted\",s.reached,\"#6366f1\",s.t?Math.round(s.reached/s.t*100):0],\n    [\"Replied\",s.replied,\"#0ea5e9\",s.t?Math.round(s.replied/s.t*100):0],[\"Scheduled\",s.sched,\"#f59e0b\",s.t?Math.round(s.sched/s.t*100):0],\n    [\"Sold PT\",s.sold,\"#22c55e\",s.t?Math.round(s.sold/s.t*100):0]];\n  var maxV=Math.max(s.t,1);\n  document.getElementById(\"funnel\").innerHTML=steps.map(function(st){\n    var w=Math.max(12,Math.round(st[1]/maxV*100));\n    return '<div class=\"fr\"><div class=\"flabel\">'+st[0]+'</div><div class=\"fbar\" style=\"background:'+st[2]+';width:'+w+'%;\">'+st[1]+'</div><div class=\"fpct\">'+st[3]+'%</div></div>';\n  }).join(\"\");\n  // 7-day chart\n  var days=[],maxD=1;\n  for(var i=6;i>=0;i--){var dt=new Date();dt.setDate(dt.getDate()-i);var k=dayKeyOf(dt);\n    var tx=state.events.filter(function(e){return e.type===\"text\"&&dayKeyOf(new Date(e.at))===k;}).length;\n    var sc=state.events.filter(function(e){return e.type===\"schedule\"&&dayKeyOf(new Date(e.at))===k;}).length;\n    maxD=Math.max(maxD,tx+sc);days.push({lbl:[\"Su\",\"Mo\",\"Tu\",\"We\",\"Th\",\"Fr\",\"Sa\"][dt.getDay()],tx:tx,sc:sc});}\n  document.getElementById(\"chart\").innerHTML=days.map(function(d){\n    var th=Math.round(d.tx/maxD*100),sh=Math.round(d.sc/maxD*100);\n    return '<div class=\"col\"><div class=\"stk\" style=\"height:'+Math.max(2,th+sh)+'%;\"><div style=\"background:#6366f1;height:'+(d.tx?d.tx/(d.tx+d.sc||1)*100:0)+'%;\"></div><div style=\"background:#22c55e;height:'+(d.sc?d.sc/(d.tx+d.sc||1)*100:0)+'%;\"></div></div><div class=\"day\">'+d.lbl+'</div></div>';\n  }).join(\"\");\n  document.getElementById(\"allTime\").innerHTML=[[\"\\ud83d\\udcac\",\"Reply %\",s.reply+\"%\"],[\"\\ud83d\\udcc5\",\"Sched %\",s.schedR+\"%\"],[\"\\ud83c\\udfaf\",\"Close %\",s.close+\"%\"],[\"\\ud83c\\udfc6\",\"Sold\",s.sold]].map(function(p){return '<div class=\"stat\"><div style=\"font-size:15px;margin-bottom:2px;\">'+p[0]+'</div><div class=\"v\">'+p[2]+'</div><div class=\"l\">'+p[1]+'</div></div>';}).join(\"\");\n  var soldLeads=state.leads.filter(function(l){return l.stage===\"sold\";});\n  var salesTotal=soldLeads.reduce(function(a,l){return a+(l.saleValue||0);},0);\n  var mk=new Date();var mnk=mk.getFullYear()+\"-\"+(mk.getMonth()+1);\n  var lm=new Date(mk.getFullYear(),mk.getMonth()-1,1);var lmk=lm.getFullYear()+\"-\"+(lm.getMonth()+1);\n  function monthSum(key){return state.events.filter(function(e){var d=new Date(e.at);return e.type===\"sold\"&&(d.getFullYear()+\"-\"+(d.getMonth()+1))===key;}).reduce(function(a,e){return a+(e.amount||0);},0);}\n  var monthSales=monthSum(mnk),lastSales=monthSum(lmk);\n  var mom=lastSales>0?Math.round((monthSales-lastSales)/lastSales*100):(monthSales>0?100:0);\n  var arrow=mom>0?'\\u2191':(mom<0?'\\u2193':'');\n  var momTxt=(arrow?arrow+Math.abs(mom)+\"% vs last month\":\"first sales this month\");\n  document.getElementById(\"salesVal\").textContent=\"$\"+Math.round(salesTotal).toLocaleString();\n  document.getElementById(\"commVal\").textContent=\"$\"+Math.round(salesTotal*rateOf()).toLocaleString();\n  document.getElementById(\"commMonth\").innerHTML=\"$\"+Math.round(monthSales*rateOf()).toLocaleString()+\" this month\"+(monthSales>0||lastSales>0?' <span style=\"color:'+(mom>=0?\"#4ade80\":\"#f87171\")+';font-weight:700;\">'+momTxt+'</span>':'');\n  document.getElementById(\"commRate\").textContent=state.level+\" \\u00b7 \"+Math.round(rateOf()*100)+\"% \\u270e\";\n  renderLeaderboard();\n}\n\n\nfunction intakeURL(){return window.location.origin+\"/intake\";}\nfunction copyIntakeLink(){var u=intakeURL();try{if(navigator.clipboard)navigator.clipboard.writeText(u);}catch(e){}alert(\"Copied:\\n\"+u);}\nfunction showQR(){var u=intakeURL();var src=\"https://api.qrserver.com/v1/create-qr-code/?size=280x280&margin=12&data=\"+encodeURIComponent(u);\n  openOv(\"Your sign-up QR\",'<div style=\"text-align:center;\"><img src=\"'+src+'\" style=\"width:240px;height:240px;border-radius:16px;background:#fff;padding:10px;\" alt=\"QR code\"><p class=\"mini\" style=\"margin:14px 0 8px;word-break:break-all;color:#c3cee0;\">'+esc(u)+'</p><button class=\"btn\" onclick=\"copyIntakeLink()\">Copy link</button><p class=\"mini\" style=\"margin-top:12px;\">Screenshot this to print a sign for the gym floor, or drop the link in your Instagram bio. Anyone who scans it fills out the form and lands in your New Leads.</p></div>');}\nfunction renderGrow(){\n  var map={};\n  state.leads.forEach(function(l){var r=(l.referredBy||\"\").trim();if(!r)return;if(!map[r])map[r]={n:0,sold:0};map[r].n++;if(l.stage===\"sold\")map[r].sold++;});\n  var arr=Object.keys(map).map(function(k){return {name:k,n:map[k].n,sold:map[k].sold};}).sort(function(a,b){return b.n-a.n;});\n  var rb=document.getElementById(\"refBoard\");\n  if(rb){ if(!arr.length)rb.innerHTML='<div class=\"card\"><p class=\"mini\">No referrals logged yet. When adding a lead, fill in \"Referred by.\"</p></div>';\n    else rb.innerHTML=arr.map(function(r,i){return '<div class=\"lead\"><div class=\"flex1\"><div class=\"nm\">'+esc(r.name)+'</div><div class=\"mt\">'+r.n+' referred \\u00b7 '+r.sold+' sold PT</div></div><span class=\"badge\" style=\"background:#6366f122;color:#818cf8;\">#'+(i+1)+'</span></div>';}).join(\"\"); }\n  var sm={};state.leads.forEach(function(l){var s=l.source||\"Other\";sm[s]=(sm[s]||0)+1;});\n  var sk=Object.keys(sm).sort(function(a,b){return sm[b]-sm[a];});\n  var sb=document.getElementById(\"srcBoard\");\n  if(sb)sb.innerHTML=sk.map(function(s){return '<div class=\"row\" style=\"justify-content:space-between;padding:5px 0;\"><span class=\"mini\">'+esc(s)+'</span><b>'+sm[s]+'</b></div>';}).join(\"\")||'<p class=\"mini\">No leads yet.</p>';\n}\nasync function addDM(){var nm=document.getElementById(\"g_name\").value.trim();if(!nm){alert(\"Add a name or handle\");return;}var parts=nm.split(/\\s+/);var first=parts[0],last=parts.slice(1).join(\" \");var contact=document.getElementById(\"g_contact\").value.trim();var goal=document.getElementById(\"g_goal\").value.trim();var phone=digits(contact).length>=7?contact:\"\";var email=(contact.indexOf(\"@\")>=0&&contact.indexOf(\".\")>=0)?contact:\"\";var handle=(!phone&&!email)?contact:\"\";var note=goal+(handle?(goal?\" \\u00b7 \":\"\")+handle:\"\");try{await api(\"POST\",\"/api/leads\",{firstName:first,lastName:last,phone:phone,email:email,contact:(phone||email||handle),source:\"Instagram DM\",note:note,referredBy:\"\",assignedTo:TRAINER});}catch(e){}document.getElementById(\"g_name\").value=\"\";document.getElementById(\"g_contact\").value=\"\";document.getElementById(\"g_goal\").value=\"\";await refresh();alert(\"Added as an Instagram DM lead.\");}\n\n/* ---------- LEAD ACTIONS ---------- */\nasync function addLead(d){try{await api(\"POST\",\"/api/leads\",d);}catch(e){}await refresh();}\nfunction isDupe(fn,ln,phone,email){var dc=digits(phone),em=(email||\"\").toLowerCase();return state.leads.some(function(l){if(dc&&dc.length>=7&&digits(l.phone)===dc)return true;if(em&&(l.email||\"\").toLowerCase()===em)return true;return fn&&l.firstName.toLowerCase()===fn.toLowerCase()&&(l.lastName||\"\").toLowerCase()===(ln||\"\").toLowerCase();});}\nasync function moveStage(id,stage){var body={stage:stage};if(stage===\"sold\"){var _a=prompt(\"Sale amount ($) that counts toward your commission:\",\"\");var _v=_a?parseFloat((_a+\"\").replace(/[^0-9.]/g,\"\")):0;body.saleValue=isNaN(_v)?0:_v;}try{await api(\"POST\",\"/api/leads/\"+id+\"/stage\",body);}catch(e){}await refresh();openDetail(id);}\nasync function addNote(id){var v=document.getElementById(\"noteInput\").value.trim();if(!v)return;try{await api(\"POST\",\"/api/leads/\"+id+\"/note\",{text:v});}catch(e){}await refresh();openDetail(id);}\nasync function delLead(id){if(!confirm(\"Delete this lead?\"))return;try{await api(\"DELETE\",\"/api/leads/\"+id);}catch(e){}closeOv();await refresh();}\n\nfunction openOv(t,h){document.getElementById(\"ovTitle\").textContent=t;document.getElementById(\"ovBody\").innerHTML=h;document.getElementById(\"ov\").classList.add(\"on\");}\nfunction closeOv(){document.getElementById(\"ov\").classList.remove(\"on\");}\nfunction openAdd(){setTimeout(function(){var t=document.getElementById(\"f_type\");if(t)t.value=leadType;},0);openOv(\"New Lead\",'<label class=\"fld\"><span>First name *</span><input class=\"inp\" id=\"f_first\"></label><label class=\"fld\"><span>Last name</span><input class=\"inp\" id=\"f_last\"></label><label class=\"fld\"><span>Phone</span><input class=\"inp\" id=\"f_phone\" placeholder=\"901-555-0100\"></label><label class=\"fld\"><span>Email</span><input class=\"inp\" id=\"f_email\"></label><label class=\"fld\"><span>Type</span><select class=\"inp\" id=\"f_type\"><option value=\"kickoff\">Kickoff (60-min, goals)</option><option value=\"sga\">SGA (free 30-min workout)</option></select></label><label class=\"fld\"><span>Source</span><select class=\"inp\" id=\"f_source\">'+SOURCES.map(function(s){return '<option>'+s+'</option>';}).join(\"\")+'</select></label><label class=\"fld\"><span>Referred by (optional)</span><input class=\"inp\" id=\"f_referred\" placeholder=\"Client who sent them\"></label><button class=\"btn\" onclick=\"submitAdd()\">Add Lead</button>');setTimeout(function(){document.getElementById(\"f_first\").focus();},100);}\nasync function submitAdd(){var fn=document.getElementById(\"f_first\").value.trim();if(!fn){alert(\"First name required\");return;}await addLead({firstName:fn,lastName:document.getElementById(\"f_last\").value,phone:document.getElementById(\"f_phone\").value,email:document.getElementById(\"f_email\").value,source:document.getElementById(\"f_source\").value,referredBy:document.getElementById(\"f_referred\").value,type:document.getElementById(\"f_type\").value,assignedTo:TRAINER});closeOv();}\nfunction openDetail(id){\n  var l=null;state.leads.forEach(function(x){if(x.id===id)l=x;});if(!l)return;\n  var m=stageMeta(l.stage);\n  var phoneRow=l.phone&&digits(l.phone).length>=7?'<div class=\"card row\" style=\"margin-bottom:8px;\"><span style=\"flex:1;font-size:14px;\">'+esc(l.phone)+'</span><a class=\"btn sky sm\" style=\"text-decoration:none;text-align:center;\" href=\"sms:'+digits(l.phone)+'\">Text</a><a class=\"btn ghost sm\" style=\"text-decoration:none;text-align:center;\" href=\"tel:'+digits(l.phone)+'\">Call</a></div>':'';\n  var copyBtn=(l.phone&&digits(l.phone).length>=7)?'<button class=\"btn ghost sm\" style=\"width:100%;margin-bottom:8px;\" onclick=\"copyStageText(\\''+l.id+'\\')\">\\ud83d\\udccb Copy the right text for this stage</button>':'';\n  var emailRow=l.email?'<div class=\"mini\" style=\"margin-bottom:8px;\">'+esc(l.email)+'</div>':'';\n  var dexp=daysUntilExpire(l);\n  var expRow=l.expire?'<div class=\"mini\" style=\"margin-bottom:8px;\">Kickoff expires '+esc(l.expire)+(dexp!==null?' \\u00b7 <b style=\"color:'+(dexp<=3?\"#f87171\":dexp<=7?\"#fbbf24\":\"#8494ad\")+';\">'+(dexp<0?\"expired\":dexp+\" days left\")+'</b>':'')+'</div>':'';\n  var refRow=l.referredBy?'<div class=\"mini\" style=\"margin-bottom:8px;\">Referred by: <b>'+esc(l.referredBy)+'</b></div>':\"\";\n  var saleRow=l.stage===\"sold\"?'<div class=\"mini\" style=\"margin-bottom:8px;\">Sale value: <b style=\"color:#4ade80;\">$'+((l.saleValue||0).toLocaleString())+'</b> \\u00b7 <button onclick=\"editSale(\\''+l.id+'\\')\" style=\"background:none;color:var(--ind2);font-weight:700;\">edit</button></div>':'';\n  var pend=l.pending?'<div class=\"mini\" style=\"margin-bottom:8px;\">Calendar pending: <b style=\"color:'+(l.pending===\"1\"?\"#f59e0b\":\"#8494ad\")+';\">'+esc(l.pending)+'</b>'+(l.pending===\"1\"?\" (appt on calendar)\":\" (no appt yet)\")+'</div>':'';\n  function pRow(lbl,val,accent){if(!val||!(\"\"+val).trim())return '';return '<div class=\"row\" style=\"justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--line);\"><span class=\"mini\">'+lbl+'</span><span style=\"font-size:13px;color:'+(accent||\"#e7ecf5\")+';font-weight:600;\">'+esc(\"\"+val)+'</span></div>';}\n  var memberSince=l.createdAt?new Date(l.createdAt).toLocaleDateString(undefined,{month:\"short\",day:\"numeric\",year:\"numeric\"}):\"\";\n  var expTxt=l.expire?(l.expire+(dexp!==null?\" (\"+(dexp<0?\"expired\":dexp+\"d left\")+\")\":\"\")):\"\";\n  var fu=l.nextFollowUp?new Date(l.nextFollowUp+\"T00:00:00\").toLocaleDateString(undefined,{month:\"short\",day:\"numeric\"}):\"\";\n  var isClient=[\"showed\",\"sold\"].indexOf(l.stage)>=0;\n  var rows='';\n  if(isBooked(l))rows+='<div class=\"row\" style=\"justify-content:center;padding:8px 0;\"><span class=\"badge\" style=\"background:#22c55e22;color:#4ade80;font-size:12px;\">\\u2713 Already scheduled / completed a kickoff \\u2014 no outreach needed</span></div>';\n  else if(dexp!==null&&dexp>=0&&dexp<=3)rows+='<div class=\"row\" style=\"justify-content:center;padding:8px 0;\"><span class=\"badge\" style=\"background:#ef444422;color:#f87171;font-size:12px;\">\\u26a1 Expires in '+dexp+' day'+(dexp===1?'':'s')+' \\u2014 book them now</span></div>';\n  rows+=pRow(\"Goal\",l.goal);\n  rows+=pRow(\"Source\",l.source);\n  if(expTxt)rows+=pRow(\"Expires\",expTxt,dexp!==null&&dexp<=7?(dexp<=3?\"#f87171\":\"#fbbf24\"):\"#e7ecf5\");\n  rows+=pRow(\"Lead added\",memberSince);\n  rows+=pRow(\"Assigned to\",l.assignedTo,l.assignedTo?\"#a5b4fc\":\"\");\n  if(l.referredBy)rows+=pRow(\"Referred by\",l.referredBy);\n  if(fu)rows+=pRow(\"Next follow-up\",fu,\"#7dd3fc\");\n  var apptTxt=l.appointment?new Date(l.appointment).toLocaleString([], {weekday:\"short\",month:\"short\",day:\"numeric\",hour:\"numeric\",minute:\"2-digit\"}):\"\";\n  if(apptTxt)rows+=pRow(\"Appointment\",apptTxt,\"#fb923c\");\n  // client-record fields only once they've shown up or bought (otherwise this data doesn't exist yet)\n  if(isClient||l.package)rows+=pRow(\"Package sold\",l.package);\n  if(l.saleValue)rows+=pRow(\"Sale value\",\"$\"+(l.saleValue).toLocaleString(),\"#4ade80\");\n  if(isClient||l.weight)rows+=pRow(\"Weight\",l.weight);\n  if(isClient||l.bodyFat)rows+=pRow(\"Body fat\",l.bodyFat?(l.bodyFat+(/%/.test(l.bodyFat)?\"\":\"%\")):\"\");\n  if(isClient||l.measurements)rows+=pRow(\"Measurements\",l.measurements);\n  var editLabel=isClient?\"Edit &#9998;\":\"Add goal / follow-up &#9998;\";\n  var profileCard='<div class=\"card\" style=\"margin-bottom:10px;padding:6px 14px;\">'\n    +'<div class=\"row\" style=\"justify-content:space-between;padding:8px 0 6px;\"><b style=\"font-size:13px;\">Client details</b><button onclick=\"openEditProfile(\\''+l.id+'\\')\" style=\"background:none;color:var(--ind2);font-size:12px;font-weight:700;\">'+editLabel+'</button></div>'\n    +rows+(!l.assignedTo&&TRAINER?'<button class=\"btn ghost sm\" style=\"width:100%;margin:8px 0 2px;\" onclick=\"claimLead(\\''+l.id+'\\')\">Assign to me ('+esc(TRAINER)+')</button>':'')+'<button class=\"btn ghost sm\" style=\"width:100%;margin:6px 0 2px;\" onclick=\"openReassign(\\''+l.id+'\\')\">\\ud83d\\udd01 Reassign trainer</button>'+'</div>';\n    var stageBtns=STAGES.map(function(s){return '<button class=\"stage-b\" style=\"'+(l.stage===s.k?\"background:\"+s.c+\";border-color:\"+s.c+\";color:#fff;\":\"\")+'\" onclick=\"moveStage(\\''+l.id+'\\',\\''+s.k+'\\')\">'+s.l+'</button>';}).join(\"\");\n  var hist=l.history.map(function(h){return '<div class=\"h\"><span class=\"d\">'+fmtDate(h.at)+'</span><span>'+esc(h.text)+'</span></div>';}).join(\"\");\n  openOv((l.firstName+\" \"+(l.lastName||\"\")).trim(),\n    '<div class=\"row\" style=\"margin-bottom:12px;\"><span class=\"badge\" style=\"background:'+m.c+'22;color:'+m.c+';\">'+m.l+'</span><span class=\"mini\">\\u00b7 '+esc(l.source)+'</span></div>'+\n    phoneRow+copyBtn+emailRow+profileCard+\n    '<div class=\"stage-grid\">'+\n      '<button class=\"btn grn sm\" style=\"width:auto;\" onclick=\"openSchedule(\\''+l.id+'\\')\">Mark Scheduled</button>'+\n      '<button class=\"btn red sm\" style=\"width:auto;\" onclick=\"moveStage(\\''+l.id+'\\',\\'noresp\\')\">No Response</button>'+\n      '<button class=\"btn sky sm\" style=\"width:auto;\" onclick=\"moveStage(\\''+l.id+'\\',\\'sold\\')\">Sold PT</button>'+\n      '<button class=\"btn ghost sm\" style=\"width:auto;\" onclick=\"moveStage(\\''+l.id+'\\',\\'dead\\')\">Not Interested</button></div>'+\n    '<div class=\"lbl\">Or set exact stage</div><div class=\"stage-grid\">'+stageBtns+'</div>'+\n    '<button class=\"btn sky\" style=\"margin:8px 0 4px;\" onclick=\"logContact(\\''+l.id+'\\')\">Log a contact today</button>'+\n    '<div class=\"lbl\">Add note</div><div class=\"row\"><input class=\"inp\" id=\"noteInput\" placeholder=\"e.g. wants mornings, price concern\"><button class=\"btn sm\" style=\"width:auto;padding:11px 16px;\" onclick=\"addNote(\\''+l.id+'\\')\">Add</button></div>'+\n    '<div class=\"lbl\">History</div><div class=\"hist\">'+hist+'</div>'+\n    '<button class=\"btn ghost\" style=\"margin-top:16px;color:#f87171;\" onclick=\"delLead(\\''+l.id+'\\')\">Delete lead</button>');\n}\n\n/* ---------- IMPORT ---------- */\nasync function uploadReport(){\n  var f=document.getElementById(\"reportFile\").files[0];if(!f)return;\n  var res=document.getElementById(\"importResult\");\n  res.innerHTML='<p class=\"mini\" style=\"margin-top:10px;\">Reading '+esc(f.name)+'\\u2026</p>';\n  var fd=new FormData();fd.append(\"file\",f);\n  try{\n    var r=await fetch(API+\"/api/import-file\",{method:\"POST\",headers:(TOKEN?{\"Authorization\":\"Bearer \"+TOKEN}:{}),body:fd});\n    var d=await r.json();if(!r.ok)throw new Error(d.detail||\"error\");\n    res.innerHTML='<div class=\"card\" style=\"margin-top:12px;background:rgba(34,197,94,.08);border-color:rgba(34,197,94,.3);\"><p class=\"mini\" style=\"color:#86efac;\">Added '+d.added+' new'+(d.skipped?', skipped '+d.skipped+' already in list':'')+' (read '+d.parsed+' rows). Check the Pipeline tab.</p></div>';\n    await refresh();\n  }catch(e){res.innerHTML='<p class=\"mini\" style=\"margin-top:10px;color:#fca5a5;\">Couldn\\'t read that file. Try CSV/Excel, or paste the text below.</p>';}\n  document.getElementById(\"reportFile\").value=\"\";\n}\nasync function importReport(){\n  var txt=document.getElementById(\"reportBox\").value;if(!txt.trim())return;\n  var reEmail=/[A-Za-z0-9._%+\\-]+@[A-Za-z0-9.\\-]+\\.[A-Za-z]{2,}/;\n  var rePhone=/\\(?\\d{3}\\)?[\\s.\\-]?\\d{3}[\\s.\\-]?\\d{4}/g;\n  var reDate=/\\d{2}\\/\\d{2}\\/\\d{4}/g;\n  var lines=txt.split(/\\n/),arr=[];\n  lines.forEach(function(line){\n    if(!/kickoff/i.test(line)&&!reEmail.test(line))return;\n    var nameM=line.match(/([A-Za-z'\\-]+),\\s?([A-Za-z'\\-]+)/);var first=\"\",last=\"\";\n    if(nameM){last=nameM[1];first=nameM[2];}\n    var emM=line.match(reEmail);var email=emM?emM[0]:\"\";\n    var phM=line.match(rePhone);var phone=\"\";\n    if(phM&&phM.length){var d=digits(phM[0]);if(d.length===10)phone=\"(\"+d.slice(0,3)+\") \"+d.slice(3,6)+\"-\"+d.slice(6);}\n    var dts=line.match(reDate);var expire=dts&&dts.length>=2?dts[1]:\"\";\n    var pend=\"\";var pm=line.match(/KickOff\\s+([01\\-])/i);if(pm)pend=pm[1];\n    if(!first&&!email&&!phone)return;if(!first&&email)first=email;\n    arr.push({firstName:first,lastName:last,phone:phone,email:email,pending:pend,expire:expire,source:\"Kickoff report\"});\n  });\n  var res={added:0,skipped:0};try{res=await api(\"POST\",\"/api/import\",arr);}catch(e){}\n  document.getElementById(\"reportBox\").value=\"\";\n  document.getElementById(\"importResult\").innerHTML='<div class=\"card\" style=\"margin-top:12px;background:rgba(34,197,94,.08);border-color:rgba(34,197,94,.3);\"><p class=\"mini\" style=\"color:#86efac;\">Added '+res.added+' new'+(res.skipped?', skipped '+res.skipped+' already in list':'')+'. Check the Pipeline tab.</p></div>';\n  await refresh();\n}\nasync function importPaste(){var txt=document.getElementById(\"pasteBox\").value.trim();if(!txt)return;var arr=[];txt.split(/\\n/).forEach(function(line){var p=line.split(\",\");if(!p[0])return;arr.push({firstName:(p[0]||\"\").trim(),lastName:(p[1]||\"\").trim(),phone:(p[2]||\"\").trim(),email:(p[3]||\"\").trim(),source:(p[4]||\"\").trim()||\"Manual\",referredBy:(p[5]||\"\").trim(),note:(p[6]||\"\").trim()});});var res={added:0,skipped:0};try{res=await api(\"POST\",\"/api/import\",arr);}catch(e){}document.getElementById(\"pasteBox\").value=\"\";alert(\"Added \"+res.added+(res.skipped?\", skipped \"+res.skipped+\" duplicate(s)\":\"\")+\".\");await refresh();}\nfunction exportCSV(){var rows=[[\"First\",\"Last\",\"Phone\",\"Email\",\"Stage\",\"Last Contact\",\"Expire\",\"Cal Pending\"]];state.leads.forEach(function(l){rows.push([l.firstName,l.lastName,l.phone||\"\",l.email||\"\",stageMeta(l.stage).l,l.lastContact?fmtDate(l.lastContact):\"\",l.expire||\"\",l.pending||\"\"]);});var csv=rows.map(function(r){return r.map(function(c){return '\"'+(c||\"\").toString().replace(/\"/g,'\"\"')+'\"';}).join(\",\");}).join(\"\\n\");var a=document.createElement(\"a\");a.href=\"data:text/csv;charset=utf-8,\"+encodeURIComponent(csv);a.download=\"trainerhub_backup.csv\";document.body.appendChild(a);a.click();a.remove();}\nasync function resetAll(){if(!confirm(\"Erase ALL leads and stats? Export a backup first.\"))return;try{await api(\"POST\",\"/api/reset\");}catch(e){}await refresh();}\n\n/* ---------- OUTREACH ---------- */\nfunction renderTemplates(){document.getElementById(\"tplList\").innerHTML=TEMPLATES.map(function(t,i){return '<div class=\"tpl\"><div class=\"th\"><b>'+t.name+'</b><button class=\"copy\" id=\"cp'+i+'\" onclick=\"copyTpl('+i+')\">Copy</button></div><div class=\"body\">'+esc(t.body.replace(/\\[Trainer\\]/g,trainerFirst()))+'</div></div>';}).join(\"\");var sel=document.getElementById(\"queueTpl\");sel.innerHTML=TEMPLATES.map(function(t,i){return '<option value=\"'+i+'\">'+t.name+'</option>';}).join(\"\");}\nfunction copyTpl(i){var t=TEMPLATES[i].body.replace(/\\[Trainer\\]/g,trainerFirst());if(navigator.clipboard)navigator.clipboard.writeText(t);var b=document.getElementById(\"cp\"+i);b.textContent=\"Copied\";b.classList.add(\"done\");setTimeout(function(){b.textContent=\"Copy\";b.classList.remove(\"done\");},1400);}\nfunction queueLeads(){var sg=(document.getElementById(\"queueSeg\")||{}).value||\"all\";\n  var base=state.leads.filter(function(l){return l.stage===\"new\"&&!isBooked(l)&&ofType(l)&&digits(l.phone).length>=7;});\n  if(sg===\"expiring\")base=base.filter(function(l){var d=daysUntilExpire(l);return d!==null&&d>=0&&d<=7;});\n  else if(sg===\"new\")base=base.filter(function(l){return isContentLead(l);});\n  return sortByExpire(base);}\nfunction renderQueue(){\n  var q=queueLeads(),area=document.getElementById(\"queueArea\");\n  if(!q.length){area.innerHTML='<div class=\"empty\" style=\"padding:30px 10px;\">No un-texted leads with a phone number.<br><span class=\"mini\">Load your report, then come back.</span></div>';return;}\n  if(queueIdx>=q.length)queueIdx=0;var l=q[queueIdx];\n  var tplIdx=+document.getElementById(\"queueTpl\").value||0;var msg=slotFill(TEMPLATES[tplIdx].body,l.firstName);\n  var dexp=daysUntilExpire(l);\n  area.innerHTML='<div class=\"q-card\"><div class=\"q-nm\">'+esc(l.firstName)+' '+esc(l.lastName||\"\")+'</div><div class=\"q-src\">'+esc(l.source)+' \\u00b7 '+esc(l.phone)+(dexp!==null?' \\u00b7 '+(dexp<0?\"expired\":dexp+\"d left\"):\"\")+'</div><div class=\"q-prev\">'+esc(msg)+'</div><a class=\"btn grn\" style=\"text-decoration:none;display:block;text-align:center;\" href=\"sms:'+digits(l.phone)+'&body='+encodeURIComponent(msg)+'\" onclick=\"markTexted(\\''+l.id+'\\')\">Open text &amp; mark texted</a><button class=\"btn ghost\" style=\"margin-top:8px;\" onclick=\"skipQueue()\">Skip for now</button><div class=\"q-count\">'+(queueIdx+1)+' of '+q.length+' un-texted</div></div>';\n}\nfunction markTexted(id){api(\"POST\",\"/api/leads/\"+id+\"/stage\",{stage:\"reached\"}).then(function(){refresh().then(function(){renderQueue();});}).catch(function(){});}\nfunction skipQueue(){queueIdx++;renderQueue();}\nfunction renderOutreach(){renderTemplates();var a=document.getElementById(\"slot1\"),b=document.getElementById(\"slot2\");if(a)a.value=SLOT1;if(b)b.value=SLOT2;renderQueue();}\n\n/* ---------- GUIDES ---------- */\nvar OBJECTIONS=[\n {k:\"price cost money afford budget expensive pricey cheap\",q:\"It's too expensive / out of my budget\",a:\"\\\"Totally fair. Quick question \\u2014 is it the investment itself, or are you just not 100% sure it\\u2019s right for you yet?\\\" If it\\u2019s money: step down frequency (3x instead of 5x) to get them started rather than losing the sale. A started client who sees results renews.\"},\n {k:\"think consider unsure hesitant not sure\",q:\"I need to think about it\",a:\"\\\"Makes sense \\u2014 what specifically do you want to think over? Is it the schedule, the price, or whether training\\u2019s right for you?\\\" Surface the real objection; \\u2018think about it\\u2019 is almost always one of those three in disguise.\"},\n {k:\"own alone myself solo diy self\",q:\"I want to try on my own first\",a:\"\\\"I love that you want to put in the work. Most people who go solo stall out in a few weeks \\u2014 not from effort, from not knowing what to adjust. That\\u2019s exactly what I fix. Let\\u2019s do a few weeks together so you learn it right, then you\\u2019ve got it for life.\\\"\"},\n {k:\"time busy schedule hours\",q:\"I don't have time\",a:\"\\\"That\\u2019s exactly why training helps \\u2014 I make every session count so you\\u2019re not wasting an hour guessing. Even 2x30min a week gets real results. What does your week actually look like?\\\"\"},\n {k:\"spouse wife husband partner talk to\",q:\"Let me talk to my spouse\",a:\"\\\"Of course. What do you think they\\u2019ll want to know? Let\\u2019s make sure you can answer the money and the time question \\u2014 want me to put the plan in writing so it\\u2019s easy to share?\\\"\"},\n {k:\"bad experience previous trainer before burned\",q:\"I had a bad experience with a trainer before\",a:\"\\\"I hear that a lot, and I\\u2019m sorry \\u2014 a lot of trainers just count reps. Tell me what went wrong last time so I can do the opposite. Your Kickoff is free, so you can feel how I coach with zero risk.\\\"\"},\n {k:\"stick commit consistent motivation quit follow through\",q:\"I'm not sure I'll stick with it\",a:\"\\\"That\\u2019s the honest answer, and it\\u2019s exactly why having someone in your corner matters \\u2014 accountability is the whole point. Let\\u2019s start smaller so it\\u2019s easy to say yes and easy to keep.\\\"\"},\n {k:\"free session decide later kickoff just the free\",q:\"Can I just do the free session and decide later?\",a:\"\\\"Absolutely \\u2014 that\\u2019s what it\\u2019s for. Let\\u2019s get the most out of it: come ready to move, and I\\u2019ll build you a real plan. No pressure, and if it\\u2019s a fit we\\u2019ll talk next steps.\\\"\"}\n];\nvar GUIDES={\n cheatsheet:{title:\"Pre-Session Cheat Sheet\",tag:\"Glance before you close\",html:\n  '<p>Your real Crunch pricing, plus the sequence that stops people walking at the number. Skim this in the 60 seconds before a kickoff.</p>'+\n  '<h3>The order (never skip step 1)</h3>'+\n  '<p><span class=\"stepnum\">1</span><b>Goal + gap in their words.</b> \"What made you finally decide to start?\" / \"A year out, thrilled \\u2014 what changed?\" / \"What\\'s gotten in the way before?\" (answer = consistency / not knowing what to do \\u2014 what training fixes).</p>'+\n  '<p><span class=\"stepnum\">2</span><b>Coach hard, then connect.</b> \"How\\'d that feel vs. on your own?\" \\u2192 \"That\\'s what someone in your corner does.\"</p>'+\n  '<p><span class=\"stepnum\">3</span><b>Recommendation THEN price, same breath.</b> \"To hit that by fall, I\\'d put you at 3x a week \\u2014 that\\'s [price].\" No flinch.</p>'+\n  '<p><span class=\"stepnum\">4</span><b>Anchor high.</b> Show 4-5x first; 3x feels reasonable next to it. Lean on the <b>50% off today</b> to start now.</p>'+\n  '<p><span class=\"stepnum\">5</span><b>Hesitation? Ask, don\\'t discount:</b> \"Is it the investment, or are you not sure it\\'s right for you?\" Money \\u2192 step down frequency. Fit \\u2192 reassure.</p>'+\n  '<p><span class=\"stepnum\">6</span><b>Assume the close:</b> \"First session this week \\u2014 Tuesday or Thursday?\"</p>'+\n  '<h3>60-Minute Sessions</h3><table class=\"price-tbl\"><tr><th>Freq</th><th>Today</th><th>Per ses</th><th>EFT /2wk</th></tr>'+\n  '<tr><td><b>5x</b></td><td><span class=\"promo\">$300</span> <s>$600</s></td><td>$60</td><td>$600</td></tr>'+\n  '<tr><td><b>4x</b></td><td><span class=\"promo\">$260</span> <s>$520</s></td><td>$65</td><td>$520</td></tr>'+\n  '<tr><td><b>3x</b></td><td><span class=\"promo\">$210</span> <s>$420</s></td><td>$70</td><td>$420</td></tr>'+\n  '<tr><td><b>2x</b></td><td>$300</td><td>$75</td><td>$300</td></tr></table>'+\n  '<h3>30-Minute Sessions</h3><table class=\"price-tbl\"><tr><th>Freq</th><th>Today</th><th>Per ses</th><th>EFT /2wk</th></tr>'+\n  '<tr><td><b>5x</b></td><td><span class=\"promo\">$175</span> <s>$350</s></td><td>$35</td><td>$350</td></tr>'+\n  '<tr><td><b>4x</b></td><td><span class=\"promo\">$160</span> <s>$320</s></td><td>$40</td><td>$320</td></tr>'+\n  '<tr><td><b>3x</b></td><td><span class=\"promo\">$135</span> <s>$270</s></td><td>$45</td><td>$270</td></tr>'+\n  '<tr><td><b>2x</b></td><td>$200</td><td>$50</td><td>$200</td></tr></table>'+\n  '<p class=\"mini\">Downgrade only: 1x/wk 60min $80/ses ($160/2wk) \\u00b7 30min $55/ses ($110/2wk). 2-5x EFT deactivates after 90 days or 6 drafts; 1x after 6 months or 12 drafts.</p>'+\n  '<div class=\"callout\"><div class=\"cl-t\">Say the frequency line</div><p>Their own sheet says it: <b>higher frequency = faster results.</b> Recommend 3x minimum; the 50% promo makes 3-5x the obvious pick. Selling 2x leaves results and revenue on the table.</p></div>'+\n  '<div class=\"callout\"><div class=\"cl-t\">Per-session reframe</div><p>\"About $70 a session \\u2014 less than what you\\'d waste guessing on your own for months and probably quitting.\"</p></div>'},\n pricing:{title:\"The Price Conversation\",tag:\"Why people walk \\u2014 and the fix\",html:\n  '<p>People walk when the price is the <b>first real thing</b> they react to. It\\'s a <b>sequencing</b> problem. Make the value undeniable and the number expected before you say it.</p>'+\n  '<h3>1. Goal + gap, their words</h3><p>Get the goal out loud, then what\\'s stopped them \\u2014 almost always consistency or not knowing what to do. That\\'s what training sells.</p>'+\n  '<div class=\"quote\">\"What made you finally decide to start?\" \\u00b7 \"A year out, thrilled \\u2014 what changed?\" \\u00b7 \"What\\'s gotten in the way?\"</div>'+\n  '<h3>2. Coach hard, then connect</h3><p>Good rep in the 30, then: \"How\\'d that feel vs. on your own?\" \\u2192 \"That\\'s having someone in your corner.\"</p>'+\n  '<h3>3. Recommendation before the number</h3><div class=\"quote\">\"To get you there by fall, I\\'d put you at 3x a week \\u2014 that\\'s [price], here\\'s what it gets you.\"</div>'+\n  '<h3>4. Anchor, then simplify</h3><p>Show 4-5x first so 3x feels reasonable. Use 50%-off-today as the reason to start now.</p>'+\n  '<h3>5. Hesitation = a question</h3><div class=\"quote\">\"Is it the investment, or are you just not sure it\\'s right for you?\"</div>'+\n  '<ul><li><b>Fit:</b> reassure, tie to the goal.</li><li><b>Money:</b> step down frequency, don\\'t kill the sale. A started client who sees results renews.</li></ul>'+\n  '<h3>6. Assume the close</h3><div class=\"quote\">\"First session this week \\u2014 Tuesday or Thursday?\"</div>'+\n  '<div class=\"callout\"><div class=\"cl-t\">The mindset</div><p>You\\'re handing them the fix to the problem they just described, not selling an expense. Real budget walk-aways: start smaller, keep them warm, follow up.</p></div>'},\n clientele:{title:\"Building Your Clientele\",tag:\"Beyond the kickoff list\",html:\n  '<p>You can bring people to Crunch and get paid on membership + packages, so every lead feeds the gym and your commission.</p>'+\n  '<h3>1. Work the gym floor</h3><p>Warmest leads are already in the building. \"You getting what you want out of your workouts?\" turns a stranger into a kickoff. Ask the front desk to send new joins your way.</p>'+\n  '<h3>2. Referrals \\u2014 free and fastest</h3><div class=\"quote\">\"If you\\'ve got a friend who\\'d want a free Kickoff, send them my way.\" (every session)</div>'+\n  '<h3>3. Content (long game)</h3><p>POV glasses clips answering beginner questions; bio: \"Trainer @ Crunch Cordova \\u2014 free assessment, DM me.\" Same CTA every post. Week-1 plan on the Content tab.</p>'+\n  '<h3>4. Local groups</h3><p>Bartlett/Arlington/Cordova/Lakeland Facebook groups are where people ask \"know a good trainer?\" Be the helpful familiar face. Ask your manager to share your content on the Crunch Cordova page.</p>'+\n  '<h3>5. Booths & bring-a-friend days</h3><p>Sign-up sheets feed straight into your pipeline. Crunch usually loves these.</p>'+\n  '<div class=\"warn\"><p>You can funnel people to Crunch. Training members privately on the side is what big-box contracts usually prohibit \\u2014 read yours first.</p></div>'},\n content:{title:\"Glasses Content Plan\",tag:\"Week 1, ready to film\",html:\n  '<p>POV, 20-45 sec. Hook in the first 2 seconds decides if anyone watches. Every caption ends with the same CTA.</p>'+\n  '<div class=\"callout\"><div class=\"cl-t\">Bio</div><p>Personal Trainer @ Crunch Cordova \\u00b7 Cordova / Bartlett / Arlington \\u00b7 Free assessment \\u2014 DM me.</p></div>'+\n  '<h3>Day 1 \\u2014 \"The machine everyone uses wrong\"</h3><p>Cable or lat pulldown. \"You\\'re probably doing this wrong.\" Two mistakes, then the fix.</p>'+\n  '<h3>Day 2 \\u2014 \"First day, what do I do?\"</h3><p>POV floor walk, 3-machine starter circuit. Removes intimidation \\u2014 highest-conversion post.</p>'+\n  '<h3>Day 3 \\u2014 A real kickoff (member OK on camera)</h3><p>\"What a free assessment actually looks like.\" Showing the thing you want booked IS the sell.</p>'+\n  '<h3>Day 4 \\u2014 Quick win</h3><p>\"You don\\'t need 2 hours in the gym.\" A 20-min full-body idea.</p>'+\n  '<h3>Day 5 \\u2014 Client win or your \"why\"</h3><p>People buy the trainer before the training.</p>'+\n  '<div class=\"callout\"><div class=\"cl-t\">Two rules</div><p>Reply to every comment. Answer every DM fast, move to scheduling, log it as a lead.</p></div>'+\n  '<div class=\"warn\"><p>Get spoken consent before filming any member, and clear Crunch\\'s in-club recording policy with your manager first.</p></div>'},\n outreach:{title:\"Outreach & Follow-up\",tag:\"Where the money hides\",html:\n  '<p>60 texts \\u2192 3 replies \\u2192 1 booked is a message-and-cadence problem, and it\\'s fixable.</p>'+\n  '<h3>Front-load the hook</h3><p>Hook line one, offer one sentence, choice-close. Long texts from unknown numbers get ignored.</p>'+\n  '<h3>Close with a choice</h3><p>\"Wednesday 6 or Saturday 10?\" beats \"want to schedule?\" every time.</p>'+\n  '<h3>Follow-up = your other 57 people</h3><ul><li>Text the day they pay.</li><li>No reply ~24h \\u2192 one nudge.</li><li>Still nothing \\u2192 <b>call.</b> Voice closes text-ignorers.</li></ul>'+\n  '<h3>Lead with expiring kickoffs</h3><p>Someone losing their free session in 3 days is your easiest yes \\u2014 the \"Expiring\" filter and the urgency template are built for exactly that.</p>'}\n};\nfunction renderGuideTabs(){var tabs=[[\"cheatsheet\",\"Cheat Sheet\"],[\"objections\",\"Objections\"],[\"pricing\",\"Pricing\"],[\"clientele\",\"Clientele\"],[\"content\",\"Content\"],[\"outreach\",\"Outreach\"]];document.getElementById(\"guideTabs\").innerHTML=tabs.map(function(t){return '<button class=\"chip '+(guideTab===t[0]?\"on\":\"\")+'\" onclick=\"setGuide(\\''+t[0]+'\\')\">'+t[1]+'</button>';}).join(\"\");if(guideTab===\"objections\"){renderObjections(\"\");return;}var g=GUIDES[guideTab];document.getElementById(\"guideBody\").innerHTML='<h2>'+g.title+'</h2><div class=\"tag\">'+g.tag+'</div>'+g.html;}\nfunction renderObjections(q){\n  q=(q||\"\").toLowerCase();\n  var list=OBJECTIONS.filter(function(o){return !q||o.q.toLowerCase().indexOf(q)>=0||o.a.toLowerCase().indexOf(q)>=0||(o.k||\"\").toLowerCase().indexOf(q)>=0;});\n  var cards=list.map(function(o){return '<div class=\"card\" style=\"margin-bottom:10px;\"><div style=\"font-weight:700;color:#fff;font-size:14px;margin-bottom:6px;\">\\u201c'+esc(o.q)+'\\u201d</div><div style=\"font-size:13.5px;color:#c3cee0;line-height:1.55;\">'+esc(o.a)+'</div></div>';}).join(\"\")||'<p class=\"mini\">No match \\u2014 try another word.</p>';\n  document.getElementById(\"guideBody\").innerHTML='<h2>Objection Handler</h2><div class=\"tag\">What to say when they hesitate</div><input class=\"search\" id=\"objSearch\" placeholder=\"Type what they said\\u2026 (price, time, spouse\\u2026)\" oninput=\"renderObjections(this.value)\" value=\"'+esc(q)+'\" style=\"margin-bottom:12px;\">'+cards;\n  var s=document.getElementById(\"objSearch\");if(s&&q){s.focus();s.setSelectionRange(q.length,q.length);}\n}\nfunction setGuide(k){guideTab=k;renderGuideTabs();window.scrollTo(0,0);}\n\nvar TABS=[\n {k:\"pipeline\",l:\"Pipeline\",ic:'<path d=\"M3 3v18h18\"/><rect x=\"7\" y=\"10\" width=\"3\" height=\"7\"/><rect x=\"12\" y=\"6\" width=\"3\" height=\"11\"/><rect x=\"17\" y=\"13\" width=\"3\" height=\"4\"/>'},\n {k:\"agenda\",l:\"Agenda\",ic:'<rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M16 2v4M8 2v4M3 10h18\"/>'},\n {k:\"stats\",l:\"Stats\",ic:'<path d=\"M3 3v18h18\"/><path d=\"m19 9-5 5-4-4-3 3\"/>'},\n {k:\"grow\",l:\"Grow\",ic:'<path d=\"M12 20v-6\"/><path d=\"M12 14l-4-4\"/><path d=\"M12 14l4-4\"/><circle cx=\"12\" cy=\"5\" r=\"2\"/><path d=\"M6 20h12\"/>'},\n {k:\"import\",l:\"Import\",ic:'<path d=\"M12 3v12\"/><path d=\"m7 10 5 5 5-5\"/><path d=\"M5 21h14\"/>'},\n {k:\"outreach\",l:\"Queue\",ic:'<path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/>'},\n {k:\"guides\",l:\"Guides\",ic:'<path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"/><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z\"/>'}\n];\nfunction navBadge(k){\n  if(k===\"pipeline\")return followUps().length+expiringSoon().filter(function(l){var d=daysUntilExpire(l);return d!==null&&d>=0&&d<=3;}).length;\n  if(k===\"agenda\")return appointmentsToday().length;\n  return 0;\n}\nfunction renderNav(){document.getElementById(\"nav\").innerHTML=TABS.map(function(t){var b=navBadge(t.k);var badge=b>0?'<span class=\"nav-badge\">'+(b>9?\"9+\":b)+'</span>':'';return '<button class=\"'+(t.k===current?\"on\":\"\")+'\" onclick=\"go(\\''+t.k+'\\')\">'+badge+'<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">'+t.ic+'</svg>'+t.l+'</button>';}).join(\"\");}\nfunction go(k){current=k;var vs=document.querySelectorAll(\".view\");for(var i=0;i<vs.length;i++)vs[i].classList.remove(\"on\");document.getElementById(\"v-\"+k).classList.add(\"on\");document.getElementById(\"fab\").style.display=(k===\"pipeline\")?\"flex\":\"none\";renderNav();window.scrollTo(0,0);if(k===\"outreach\")renderOutreach();if(k===\"guides\")renderGuideTabs();if(k===\"stats\")renderStats();if(k===\"grow\")renderGrow();if(k===\"agenda\")renderAgenda();if(k===\"import\")renderTeam();}\n\nrenderNav();renderGuideTabs();boot();\ndocument.getElementById(\"ov\").addEventListener(\"click\",function(e){if(e.target.id===\"ov\")closeOv();});\n</script>\n</body>\n</html>"

INTAKE_HTML = "<!DOCTYPE html><html lang=\"en\"><head>\n<meta charset=\"UTF-8\"/><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\"/>\n<title>Claim Your Free Kickoff \u00b7 Crunch Cordova</title>\n<link rel=\"apple-touch-icon\" href=\"data:image/png;base64,\"><link rel=\"icon\" type=\"image/png\" href=\"data:image/png;base64,\">\n<style>\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}\nhtml,body{margin:0;padding:0;background:#0b1120;color:#e7ecf5;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;-webkit-font-smoothing:antialiased;}\nbody{background:radial-gradient(120% 80% at 50% -10%,#241a5e 0%,#0b1120 60%);min-height:100vh;}\n.wrap{max-width:460px;margin:0 auto;padding:28px 20px 60px;}\n.top{text-align:center;margin-bottom:22px;}\n.ic{width:78px;height:78px;border-radius:20px;box-shadow:0 10px 30px rgba(79,70,229,.4);}\nh1{font-size:25px;font-weight:900;letter-spacing:-.5px;margin:16px 0 6px;line-height:1.15;}h1 span{color:#818cf8;}\n.sub{font-size:14px;color:#9aa8c2;line-height:1.5;}\n.free{display:inline-block;background:linear-gradient(90deg,#f97316,#f59e0b);color:#1a1200;font-weight:800;font-size:12px;letter-spacing:.5px;padding:5px 12px;border-radius:99px;margin-bottom:6px;text-transform:uppercase;}\n.card{background:#111a2e;border:1px solid #1e293b;border-radius:18px;padding:18px;margin-top:8px;}\nlabel{display:block;font-size:12px;color:#8494ad;margin:0 0 6px;}.fld{margin-bottom:14px;}\ninput,select{width:100%;background:#0f1626;border:1px solid #24324a;border-radius:12px;padding:13px;font-size:16px;color:#e7ecf5;outline:none;}\ninput:focus,select:focus{border-color:#6366f1;}\n.btn{width:100%;background:linear-gradient(90deg,#4f46e5,#0ea5e9);color:#fff;font-weight:800;font-size:17px;padding:15px;border-radius:14px;border:none;margin-top:4px;box-shadow:0 8px 22px rgba(79,70,229,.35);}\n.btn:active{transform:scale(.99);}.btn:disabled{opacity:.6;}\n.bullets{list-style:none;padding:0;margin:16px 0 0;}.bullets li{font-size:13px;color:#c3cee0;padding:6px 0 6px 24px;position:relative;}\n.bullets li::before{content:\"\\2713\";position:absolute;left:0;color:#22c55e;font-weight:900;}\n.note{font-size:11px;color:#5b6b85;text-align:center;margin-top:16px;line-height:1.5;}\n.ok{text-align:center;padding:26px 0;}.ok .big{font-size:56px;}.ok h2{font-size:22px;font-weight:800;margin:8px 0;}.ok p{color:#9aa8c2;font-size:14px;line-height:1.55;}\n.hidden{display:none;}.err{color:#fca5a5;font-size:13px;margin-top:10px;text-align:center;}\n</style></head><body>\n<div class=\"wrap\">\n  <div class=\"top\">\n    <img class=\"ic\" src=\"data:image/png;base64,\" alt=\"\">\n    <div style=\"margin-top:14px;\"><span class=\"free\">Free \u00b7 Included with membership</span></div>\n    <h1>Claim your <span>free Kickoff</span><br>at Crunch Cordova</h1>\n    <p class=\"sub\">A 60-minute session with a trainer &mdash; goal-setting, a fitness assessment, and a 30-minute workout built for you. New or experienced, it's the best way to start.</p>\n  </div>\n  <div class=\"card\" id=\"formCard\">\n    <div class=\"fld\"><label>First name *</label><input id=\"first\" autocomplete=\"given-name\"></div>\n    <div class=\"fld\"><label>Last name</label><input id=\"last\" autocomplete=\"family-name\"></div>\n    <div class=\"fld\"><label>Cell phone *</label><input id=\"phone\" type=\"tel\" autocomplete=\"tel\" placeholder=\"(901) 555-0123\"></div>\n    <div class=\"fld\"><label>Email</label><input id=\"email\" type=\"email\" autocomplete=\"email\"></div>\n    <div class=\"fld\"><label>Your main goal</label><select id=\"goal\">\n      <option>Lose weight</option><option>Build muscle / tone</option><option>Get stronger</option>\n      <option>General fitness / feel better</option><option>Not sure yet</option></select></div>\n    <div class=\"fld\"><label>Who referred you? (optional)</label><input id=\"referred\" placeholder=\"Friend or member's name\"></div>\n    <button class=\"btn\" id=\"submitBtn\" onclick=\"submitForm()\">Get My Free Session</button>\n    <div class=\"err hidden\" id=\"err\"></div>\n    <ul class=\"bullets\">\n      <li>100% free &mdash; already included with your membership</li>\n      <li>A trainer reaches out to lock in your time</li>\n      <li>No pressure, just a real plan for your goals</li>\n    </ul>\n  </div>\n  <div class=\"card ok hidden\" id=\"okCard\">\n    <div class=\"big\">&#127881;</div><h2>You're on the list!</h2>\n    <p>Your trainer will reach out shortly to get you scheduled. Keep an eye on your texts!</p>\n  </div>\n  <p class=\"note\">Crunch Cordova &middot; Serving Cordova, Bartlett &amp; Arlington</p>\n</div>\n<script>\nfunction digits(s){return (s||\"\").replace(/[^0-9]/g,\"\");}\nasync function submitForm(){\n  var first=document.getElementById(\"first\").value.trim();\n  var phone=document.getElementById(\"phone\").value.trim();\n  var err=document.getElementById(\"err\");\n  if(!first||digits(phone).length<7){err.textContent=\"Please add your name and a valid phone.\";err.classList.remove(\"hidden\");return;}\n  err.classList.add(\"hidden\");\n  var btn=document.getElementById(\"submitBtn\");btn.disabled=true;btn.textContent=\"Sending...\";\n  var payload={first:first,last:document.getElementById(\"last\").value.trim(),phone:phone,email:document.getElementById(\"email\").value.trim(),goal:document.getElementById(\"goal\").value,referred:document.getElementById(\"referred\").value.trim()};\n  try{\n    var r=await fetch(\"/api/intake\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(payload)});\n    if(!r.ok)throw new Error(\"bad\");\n    document.getElementById(\"formCard\").classList.add(\"hidden\");\n    document.getElementById(\"okCard\").classList.remove(\"hidden\");\n    window.scrollTo(0,0);\n  }catch(e){\n    btn.disabled=false;btn.textContent=\"Get My Free Session\";\n    err.textContent=\"Something went wrong. Please try again.\";err.classList.remove(\"hidden\");\n  }\n}\n</script></body></html>"
